window.QBANK = window.QBANK || {};
window.QBANK["sd-ipa"] = {
  level: "SD", subject: "IPA", duration: 900,
  questions: [
    { q: "Tumbuhan membuat makanannya sendiri melalui proses fotosintesis. Salah satu bahan yang dibutuhkan dalam fotosintesis adalah ...", options: ["cahaya matahari", "angin kencang", "suara burung", "tanah kering"], answer: 0, solution: "1. Fotosintesis adalah proses tumbuhan membuat makanan. 2. Bahan yang dibutuhkan: air, karbon dioksida, dan cahaya matahari. 3. Cahaya matahari memberi energi agar prosesnya berjalan." },
    { q: "Bagian tumbuhan yang berfungsi menyerap air dan zat hara dari tanah adalah ...", options: ["daun", "batang", "akar", "bunga"], answer: 2, solution: "1. Akar adalah bagian tumbuhan yang tumbuh di dalam tanah. 2. Ujung akar menyerap air dan zat hara dari tanah. 3. Air dan zat hara itu lalu disalurkan ke batang dan daun." },
    { q: "Hewan berikut yang termasuk mamalia (hewan menyusui) adalah ...", options: ["katak", "kucing", "ikan lele", "kupu-kupu"], answer: 1, solution: "1. Mamalia adalah hewan yang menyusui anaknya. 2. Ciri mamalia: berbulu dan bernapas dengan paru-paru. 3. Kucing menyusui anaknya, jadi kucing termasuk mamalia." },
    { q: "Air yang dimasukkan ke dalam freezer akan berubah menjadi es. Perubahan wujud ini disebut ...", options: ["menguap", "mencair", "membeku", "menyublim"], answer: 2, solution: "1. Air mula-mula berwujud cair. 2. Di dalam freezer suhunya sangat dingin. 3. Perubahan wujud dari cair menjadi padat (es) disebut membeku." },
    { q: "Magnet dapat menarik benda yang terbuat dari ...", options: ["kayu", "besi", "plastik", "kertas"], answer: 1, solution: "1. Magnet hanya menarik benda dari logam tertentu. 2. Besi, baja, dan nikel dapat ditarik oleh magnet. 3. Kayu, plastik, dan kertas tidak dapat ditarik magnet." },
    { q: "Organ tubuh manusia yang menjadi tempat pertukaran oksigen dan karbon dioksida adalah ...", options: ["jantung", "paru-paru", "hati", "ginjal"], answer: 1, solution: "1. Saat menarik napas, udara masuk ke paru-paru. 2. Di dalam paru-paru, oksigen diserap oleh darah. 3. Karbon dioksida dikeluarkan saat kita menghembuskan napas." },
    { q: "Contoh sumber energi terbarukan adalah ...", options: ["batu bara", "matahari", "bensin", "gas alam"], answer: 1, solution: "1. Energi terbarukan adalah energi yang tidak akan habis. 2. Matahari bersinar setiap hari dan tidak habis dipakai. 3. Batu bara, bensin, dan gas alam dapat habis karena butuh jutaan tahun untuk terbentuk." },
    { q: "Dalam rantai makanan, makhluk hidup yang berperan sebagai produsen adalah ...", options: ["tumbuhan hijau", "kelinci", "elang", "ular"], answer: 0, solution: "1. Produsen adalah makhluk hidup yang membuat makanannya sendiri. 2. Tumbuhan hijau membuat makanan melalui fotosintesis. 3. Hewan disebut konsumen karena mendapatkan energi dengan memakan tumbuhan atau hewan lain." },
    { q: "Sifat cahaya yang benar adalah ...", options: ["merambat lurus", "berbelok-belok", "tidak dapat dipantulkan", "menembus semua benda"], answer: 0, solution: "1. Cahaya selalu merambat lurus. 2. Buktinya: bayangan benda bentuknya mengikuti bentuk bendanya. 3. Cahaya memang bisa dipantulkan cermin, tapi jalannya tetap lurus." },
    { q: "Tulang yang melindungi otak manusia adalah ...", options: ["tulang rusuk", "tulang tengkorak", "tulang paha", "tulang belakang"], answer: 1, solution: "1. Otak adalah organ yang sangat penting dan lunak. 2. Otak dibungkus oleh tulang tengkorak yang keras. 3. Tulang rusuk melindungi jantung dan paru-paru, bukan otak." },
    { q: "Tumbuhan putri malu menutup daunnya ketika disentuh. Hal ini menunjukkan bahwa tumbuhan ...", options: ["peka terhadap rangsang", "dapat berpindah tempat", "tidak membutuhkan air", "tidak bernapas"], answer: 0, solution: "1. Salah satu ciri makhluk hidup adalah peka terhadap rangsang (tanggap pada sentuhan, cahaya, dan lain-lain). 2. Putri malu menutup daun saat disentuh sebagai tanggapannya. 3. Jadi tumbuhan juga peka terhadap rangsang, walaupun tidak bisa berpindah tempat." },
    { q: "Daun berperan penting bagi tumbuhan karena menjadi tempat ...", options: ["fotosintesis", "menyerap air", "menegakkan tumbuhan", "menyerap zat hara"], answer: 0, solution: "1. Daun memiliki zat hijau daun (klorofil). 2. Dengan klorofil dan cahaya matahari, daun membuat makanan melalui fotosintesis. 3. Menyerap air dan zat hara adalah tugas akar, menegakkan tumbuhan adalah tugas batang." },
    { q: "Tumbuhan yang berkembang biak dengan umbi batang adalah ...", options: ["kentang", "mangga", "bawang merah", "jahe"], answer: 0, solution: "1. Umbi batang adalah batang yang membesar di dalam tanah untuk menyimpan cadangan makanan. 2. Contohnya kentang. 3. Bawang merah berkembang biak dengan umbi lapis, jahe dengan rimpang, mangga dengan biji." },
    { q: "Urutan metamorfosis kupu-kupu yang benar adalah ...", options: ["telur → kepompong → ulat → kupu-kupu", "telur → ulat → kepompong → kupu-kupu", "ulat → telur → kupu-kupu → kepompong", "telur → kupu-kupu → ulat → kepompong"], answer: 1, solution: "1. Metamorfosis kupu-kupu terdiri dari 4 tahap. 2. Urutannya: telur menetas menjadi ulat (larva), ulat berubah menjadi kepompong (pupa), lalu keluar menjadi kupu-kupu dewasa. 3. Jadi urutan yang benar: telur → ulat → kepompong → kupu-kupu." },
    { q: "Ketika lampu dinyalakan, perubahan energi yang terjadi adalah ...", options: ["energi listrik menjadi energi cahaya", "energi cahaya menjadi energi listrik", "energi panas menjadi energi gerak", "energi kimia menjadi energi bunyi"], answer: 0, solution: "1. Lampu membutuhkan listrik agar bisa menyala. 2. Setelah menyala, lampu menghasilkan cahaya (dan sedikit panas). 3. Jadi energi listrik berubah menjadi energi cahaya." },
    { q: "Bendungan (dam) pada pembangkit listrik memanfaatkan energi ...", options: ["air yang mengalir", "angin yang bertiup", "matahari yang bersinar", "minyak bumi"], answer: 0, solution: "1. Air yang dibendung lalu dialirkan dapat memutar turbin. 2. Putaran turbin menghasilkan listrik (PLTA). 3. Jadi bendungan memanfaatkan energi air yang mengalir." },
    { q: "Buah yang sudah matang jatuh dari pohon ke tanah karena pengaruh gaya ...", options: ["gravitasi", "magnet", "gesek", "otot"], answer: 0, solution: "1. Gaya gravitasi adalah gaya tarik bumi terhadap semua benda. 2. Gaya ini menarik buah ke arah bawah, yaitu ke tanah. 3. Gaya magnet hanya menarik besi, sedangkan gaya otot berasal dari makhluk hidup." },
    { q: "Ban kendaraan dibuat beralur dengan tujuan ...", options: ["agar tidak mudah selip", "agar terlihat bagus", "agar cepat rusak", "agar lebih ringan"], answer: 0, solution: "1. Alur pada ban memperbesar gaya gesek antara ban dan jalan. 2. Gaya gesek yang besar membuat ban mencengkeram jalan dengan kuat. 3. Akibatnya kendaraan tidak mudah selip, terutama di jalan yang basah." },
    { q: "Dalam daur air, uap air yang naik ke udara kemudian ...", options: ["membeku menjadi es", "mengembun menjadi awan", "berubah menjadi minyak", "hilang begitu saja"], answer: 1, solution: "1. Air laut menguap karena panas matahari menjadi uap air. 2. Uap air naik ke tempat yang lebih dingin. 3. Di sana uap air mengembun (kondensasi) menjadi titik-titik air pembentuk awan." },
    { q: "Planet yang paling dekat dengan matahari adalah ...", options: ["Venus", "Merkurius", "Mars", "Bumi"], answer: 1, solution: "1. Urutan planet dari matahari: Merkurius, Venus, Bumi, Mars, dan seterusnya. 2. Planet pertama berarti paling dekat dengan matahari. 3. Jadi jawabannya Merkurius." },
    { q: "Terjadinya siang dan malam disebabkan oleh ...", options: ["rotasi bumi", "revolusi bumi", "revolusi bulan", "gerak planet Mars"], answer: 0, solution: "1. Rotasi adalah perputaran bumi pada porosnya. 2. Bagian bumi yang menghadap matahari mengalami siang, yang membelakangi mengalami malam. 3. Revolusi bumi mengelilingi matahari menyebabkan pergantian musim, bukan siang dan malam." },
    { q: "Bulan yang terlihat bulat penuh di langit malam disebut bulan ...", options: ["sabit", "purnama", "separuh", "gerhana"], answer: 1, solution: "1. Bentuk bulan terlihat berubah-ubah karena posisinya terhadap matahari. 2. Saat seluruh permukaan bulan yang menghadap bumi terkena cahaya, bulan terlihat bulat penuh. 3. Fase ini disebut bulan purnama." },
    { q: "Fungsi rangka bagi tubuh manusia adalah ...", options: ["menegakkan tubuh dan melindungi organ dalam", "memompa darah ke seluruh tubuh", "mencerna makanan", "menyaring udara kotor"], answer: 0, solution: "1. Rangka adalah susunan tulang-tulang tubuh. 2. Rangka membuat tubuh bisa tegak berdiri. 3. Rangka juga melindungi organ penting, misalnya tulang tengkorak melindungi otak." },
    { q: "Bagian telinga yang berfungsi menangkap getaran suara adalah ...", options: ["daun telinga", "gendang telinga", "tulang pendengaran", "saluran telinga"], answer: 1, solution: "1. Suara masuk melalui daun telinga dan saluran telinga. 2. Getaran suara lalu ditangkap oleh gendang telinga yang ikut bergetar. 3. Getaran diteruskan oleh tulang-tulang pendengaran ke saraf." },
    { q: "Daun kaktus berbentuk duri. Bentuk ini berfungsi untuk ...", options: ["mengurangi penguapan air", "menarik perhatian serangga", "menyerap lebih banyak air", "menangkap hewan mangsa"], answer: 0, solution: "1. Kaktus hidup di tempat kering seperti gurun. 2. Daun yang kecil berbentuk duri membuat air tidak cepat menguap. 3. Ini contoh penyesuaian diri (adaptasi) tumbuhan terhadap lingkungannya." },
    { q: "Salah satu cara melestarikan hewan langka adalah dengan ...", options: ["membuat penangkaran", "berburu secara liar", "menebang hutan", "membuang sampah ke sungai"], answer: 0, solution: "1. Hewan langka jumlahnya tinggal sedikit dan terancam punah. 2. Penangkaran adalah tempat merawat dan mengembangbiakkan hewan langka agar jumlahnya bertambah. 3. Berburu liar dan menebang hutan justru merusak tempat hidupnya." },
    { q: "Karet gelang dapat kembali ke bentuk semula setelah ditarik. Sifat benda seperti ini disebut ...", options: ["elastis", "keras", "rapuh", "kasar"], answer: 0, solution: "1. Benda elastis (lentur) bisa berubah bentuk saat diberi gaya. 2. Setelah gayanya hilang, benda kembali ke bentuk semula. 3. Contoh lain benda elastis: pegas dan balon." },
    { q: "Sendok logam menjadi panas ketika dipakai mengaduk teh panas. Perpindahan panas seperti ini disebut ...", options: ["konduksi", "konveksi", "radiasi", "evaporasi"], answer: 0, solution: "1. Panas berpindah dari teh panas ke sendok melalui sentuhan langsung. 2. Perpindahan panas melalui benda padat tanpa disertai perpindahan partikel disebut konduksi. 3. Logam adalah penghantar panas yang baik." },
    { q: "Pohon bakau memiliki akar yang muncul ke permukaan lumpur. Akar khusus ini berfungsi untuk ...", options: ["mendapatkan oksigen untuk bernapas", "menyerap air laut yang asin", "menahan ombak besar", "menangkap ikan kecil"], answer: 0, solution: "1. Lumpur tempat bakau tumbuh miskin oksigen. 2. Akar napas muncul ke permukaan agar bisa mengambil oksigen dari udara. 3. Ini contoh adaptasi tumbuhan bakau terhadap lingkungannya." },
    { q: "Lebah mendapatkan madu dari bunga, sedangkan bunga terbantu penyerbukannya. Hubungan ini disebut simbiosis ...", options: ["mutualisme", "parasitisme", "komensalisme", "kompetisi"], answer: 0, solution: "1. Simbiosis adalah hubungan antara dua makhluk hidup. 2. Di sini lebah untung (mendapat madu) dan bunga pun untung (terbantu penyerbukan). 3. Hubungan yang saling menguntungkan disebut simbiosis mutualisme." },
    { q: "Alat berikut yang bekerja dengan prinsip tuas dalam kehidupan sehari-hari adalah ...", options: ["ember air", "roda sepeda", "gunting", "paku payung"], answer: 2, solution: "1. Tuas adalah pesawat sederhana yang memiliki titik tumpu. 2. Gunting memiliki titik tumpu berupa baut di tengahnya. 3. Saat dipakai, gunting berputar pada titik tumpu itu untuk memotong." },
    { q: "Jalan di daerah pegunungan dibuat berkelok dan landai. Hal ini merupakan penerapan pesawat sederhana berupa ...", options: ["bidang miring", "tuas", "katrol", "roda berporos"], answer: 0, solution: "1. Jalan berkelok membuat tanjakan terasa lebih landai. 2. Permukaan yang miring dan landai ini disebut bidang miring. 3. Bidang miring memudahkan kendaraan naik ke tempat yang tinggi dengan tenaga lebih kecil." },
    { q: "Untuk mengangkat air dari dalam sumur, orang biasanya menggunakan ...", options: ["tuas", "bidang miring", "sekrup", "katrol"], answer: 3, solution: "1. Timba sumur dihubungkan dengan tali yang dililitkan pada roda. 2. Roda berputar saat tali ditarik sehingga timba terangkat. 3. Alat seperti ini disebut katrol, yang mengubah arah gaya tarik." },
    { q: "Sekrup dan baut merupakan penerapan pesawat sederhana berupa ...", options: ["tuas", "bidang miring", "katrol", "pengungkit"], answer: 1, solution: "1. Perhatikan ulir pada sekrup: bentuknya seperti jalan melingkar yang miring. 2. Ulir ini adalah bidang miring yang dililitkan. 3. Karena itu sekrup mudah masuk ke kayu saat diputar." },
    { q: "Sepeda yang dikayuh dengan kecepatan yang sama setiap detiknya dikatakan bergerak ...", options: ["lurus beraturan", "lurus berubah beraturan", "melingkar beraturan", "diam"], answer: 0, solution: "1. Gerak lurus beraturan adalah gerak dengan lintasan lurus dan kecepatan tetap. 2. Sepeda yang kecepatannya sama setiap detik berarti kecepatannya tetap. 3. Jadi sepeda itu bergerak lurus beraturan." },
    { q: "Bola yang menggelinding di lantai akhirnya berhenti karena adanya gaya ...", options: ["gravitasi", "magnet", "gesek", "otot"], answer: 2, solution: "1. Saat bola menggelinding, permukaannya bergesekan dengan lantai. 2. Gaya gesek arahnya berlawanan dengan arah gerak bola. 3. Gaya inilah yang memperlambat bola hingga berhenti." },
    { q: "Akibat revolusi bumi mengelilingi matahari adalah ...", options: ["pergantian musim", "terjadinya siang dan malam", "pasang surut air laut", "gerak semu harian matahari"], answer: 0, solution: "1. Revolusi adalah perputaran bumi mengelilingi matahari selama satu tahun. 2. Karena posisi bumi terhadap matahari berubah-ubah, tiap bagian bumi menerima panas yang berbeda-beda. 3. Hal ini menyebabkan pergantian musim di berbagai belahan bumi." },
    { q: "Gerhana matahari terjadi ketika ...", options: ["bumi berada di antara matahari dan bulan", "bulan berada di antara matahari dan bumi", "matahari berada di antara bumi dan bulan", "bulan menjauhi bumi"], answer: 1, solution: "1. Gerhana matahari terjadi saat cahaya matahari ke bumi terhalang. 2. Yang menghalangi adalah bulan yang berada di antara matahari dan bumi. 3. Akibatnya bayangan bulan jatuh ke permukaan bumi." },
    { q: "Satelit alami yang dimiliki bumi adalah ...", options: ["matahari", "planet Mars", "stasiun luar angkasa", "bulan"], answer: 3, solution: "1. Satelit adalah benda langit yang mengelilingi planet. 2. Satelit alami berarti terbentuk secara alami, bukan buatan manusia. 3. Bulan mengelilingi bumi secara alami, jadi bulan adalah satelit alami bumi." },
    { q: "Lapisan bumi tempat manusia dan makhluk hidup tinggal disebut ...", options: ["kerak bumi", "mantel bumi", "inti luar", "inti dalam"], answer: 0, solution: "1. Bumi terdiri dari beberapa lapisan dari luar ke dalam. 2. Lapisan yang paling luar dan paling tipis disebut kerak bumi. 3. Di atas kerak bumilah manusia, hewan, dan tumbuhan hidup." },
    { q: "Lapisan bumi yang suhunya paling panas adalah ...", options: ["kerak bumi", "mantel bumi", "inti dalam", "atmosfer"], answer: 2, solution: "1. Semakin ke dalam bumi, suhunya semakin panas. 2. Lapisan yang paling dalam adalah inti dalam. 3. Jadi inti dalam adalah lapisan bumi yang paling panas." },
    { q: "Perhatikan rantai makanan berikut: padi → belalang → katak → ular → elang. Yang berperan sebagai konsumen tingkat III adalah ...", options: ["belalang", "ular", "katak", "elang"], answer: 1, solution: "1. Urutan konsumen dihitung dari produsen (padi). 2. Konsumen tingkat I: belalang, tingkat II: katak, tingkat III: ular. 3. Jadi konsumen tingkat III adalah ular." },
    { q: "Kumpulan beberapa rantai makanan yang saling berhubungan dan tumpang tindih disebut ...", options: ["jaring-jaring makanan", "piramida makanan", "rantai makanan", "siklus energi"], answer: 0, solution: "1. Di alam, satu hewan bisa dimakan oleh beberapa hewan lain. 2. Beberapa rantai makanan yang saling terkait membentuk jaring yang rumit. 3. Kumpulan rantai makanan yang saling berhubungan ini disebut jaring-jaring makanan." },
    { q: "Bebek memiliki kaki yang berselaput. Kaki berselaput ini berfungsi untuk ...", options: ["mencengkeram mangsa", "berlari dengan cepat", "memanjat pohon", "berenang di air"], answer: 3, solution: "1. Bebek hidup di sekitar air seperti danau dan sawah. 2. Selaput di antara jari kakinya memperluas permukaan kaki. 3. Kaki yang lebar ini berfungsi seperti dayung sehingga bebek mudah berenang." },
    { q: "Burung elang memiliki paruh yang tajam dan melengkung. Paruh seperti ini berfungsi untuk ...", options: ["merobek daging mangsanya", "mengisap nektar bunga", "mematuk biji-bijian", "menyaring air"], answer: 0, solution: "1. Elang adalah burung pemangsa yang memakan hewan lain. 2. Paruh yang tajam dan melengkung kuat mencengkeram dan merobek. 3. Jadi paruh elang berfungsi untuk merobek daging mangsanya." },
    { q: "Contoh sumber daya alam yang tidak dapat diperbarui adalah ...", options: ["air", "matahari", "minyak bumi", "angin"], answer: 2, solution: "1. Sumber daya alam tak terbarukan adalah yang akan habis jika terus dipakai. 2. Minyak bumi terbentuk dari fosil selama jutaan tahun sehingga tidak bisa diperbarui dengan cepat. 3. Air, angin, dan matahari terus tersedia di alam." },
    { q: "Contoh pemanfaatan sumber daya alam yang bijak adalah ...", options: ["menangkap ikan dengan racun", "menanam kembali pohon yang ditebang", "menebang hutan sembarangan", "membuang sampah ke sungai"], answer: 1, solution: "1. Sumber daya alam harus dijaga agar tidak habis dan lingkungan tetap lestari. 2. Menanam kembali pohon yang ditebang (reboisasi) mengganti pohon yang dipakai. 3. Pilihan lain merusak alam: racun membunuh ikan lain, tebang sembarangan merusak hutan." },
    { q: "Contoh hewan yang daur hidupnya tidak mengalami metamorfosis sempurna adalah ...", options: ["ayam", "kupu-kupu", "katak", "nyamuk"], answer: 0, solution: "1. Metamorfosis sempurna memiliki tahap larva dan pupa (kepompong). 2. Ayam menetas dari telur langsung menjadi anak ayam yang mirip induknya. 3. Karena tidak ada tahap ulat dan kepompong, ayam tidak mengalami metamorfosis sempurna." },
    { q: "Urutan daur hidup ayam yang benar adalah ...", options: ["telur → kepompong → ayam dewasa", "anak ayam → telur → ayam dewasa", "telur → berudu → ayam dewasa", "telur → anak ayam → ayam dewasa"], answer: 3, solution: "1. Ayam berkembang biak dengan bertelur. 2. Telur dierami hingga menetas menjadi anak ayam. 3. Anak ayam tumbuh besar menjadi ayam dewasa yang bisa bertelur lagi." },
    { q: "Kadal dan cicak berkembang biak dengan cara ...", options: ["melahirkan", "bertelur", "bertunas", "membelah diri"], answer: 1, solution: "1. Kadal dan cicak termasuk hewan reptil. 2. Sebagian besar reptil berkembang biak dengan bertelur. 3. Telur kadal dan cicak menetas menjadi anak yang mirip induknya." },
{ q: "Energi yang dimiliki benda karena sedang bergerak disebut energi ....", options: ["kinetik", "potensial", "panas", "kimia"], answer: 0, solution: "1. Energi kinetik adalah energi yang dimiliki benda karena gerakannya. 2. Contohnya bola yang menggelinding dan mobil yang melaju. 3. Jadi jawaban yang benar adalah energi kinetik." },
{ q: "Anak panah yang sudah ditarik pada busur sebelum dilepaskan menyimpan energi ....", options: ["bunyi", "potensial", "kinetik", "listrik"], answer: 1, solution: "1. Energi potensial adalah energi yang tersimpan pada benda karena kedudukan atau keadaannya. 2. Busur yang ditarik menyimpan energi yang akan berubah menjadi gerak saat dilepaskan. 3. Jadi jawaban yang benar adalah energi potensial." },
{ q: "Batu yang berada di puncak bukit memiliki energi potensial yang .... dibandingkan saat berada di lembah.", options: ["lebih kecil", "sama saja", "lebih besar", "hilang"], answer: 2, solution: "1. Energi potensial gravitasi bergantung pada ketinggian benda. 2. Semakin tinggi kedudukan benda, semakin besar energi potensialnya. 3. Jadi batu di puncak bukit memiliki energi potensial lebih besar." },
{ q: "Sumber energi utama bagi kehidupan di Bumi adalah ....", options: ["bulan", "matahari", "bintang", "api"], answer: 1, solution: "1. Matahari memancarkan cahaya dan panas ke Bumi. 2. Energi matahari dipakai tumbuhan untuk fotosintesis dan menghangatkan Bumi. 3. Jadi sumber energi utama kehidupan di Bumi adalah matahari." },
{ q: "Pakaian yang dijemur di bawah terik matahari cepat kering karena ....", options: ["angin meniup airnya", "panas matahari menguapkan air", "cahaya membuat baju ringan", "matahari menyedot air"], answer: 1, solution: "1. Panas matahari menaikkan suhu air pada pakaian basah. 2. Air yang panas berubah menjadi uap air (menguap). 3. Jadi pakaian cepat kering karena panas matahari menguapkan air." },
{ q: "Ketika setrika listrik dinyalakan, perubahan energi yang terjadi adalah ....", options: ["listrik menjadi panas", "panas menjadi listrik", "gerak menjadi cahaya", "kimia menjadi bunyi"], answer: 0, solution: "1. Setrika listrik dialiri arus listrik dari stopkontak. 2. Elemen pemanas di dalamnya mengubah energi listrik menjadi energi panas. 3. Jadi perubahannya adalah energi listrik menjadi energi panas." },
{ q: "Kipas angin yang menyala mengubah energi listrik menjadi energi ....", options: ["panas", "gerak", "kimia", "bunyi"], answer: 1, solution: "1. Kipas angin menggunakan motor listrik. 2. Motor mengubah energi listrik menjadi putaran baling-baling, yaitu energi gerak. 3. Jadi kipas angin mengubah energi listrik menjadi energi gerak." },
{ q: "Pada senter yang memakai baterai, perubahan energi yang terjadi adalah ....", options: ["listrik menjadi kimia", "kimia menjadi cahaya", "gerak menjadi panas", "cahaya menjadi listrik"], answer: 1, solution: "1. Baterai menyimpan energi kimia. 2. Saat senter dinyalakan, energi kimia baterai diubah menjadi cahaya lampu. 3. Jadi perubahannya adalah energi kimia menjadi energi cahaya." },
{ q: "Televisi yang sedang menyala mengubah energi listrik menjadi energi ....", options: ["cahaya dan bunyi", "panas dan gerak", "kimia dan panas", "gerak dan kimia"], answer: 0, solution: "1. Televisi menampilkan gambar yang bisa dilihat dan suara yang bisa didengar. 2. Gambar berasal dari energi cahaya, suara berasal dari energi bunyi. 3. Jadi televisi mengubah energi listrik menjadi cahaya dan bunyi." },
{ q: "Panel surya bekerja dengan mengubah energi .... menjadi energi listrik.", options: ["angin", "cahaya matahari", "air", "panas bumi"], answer: 1, solution: "1. Panel surya dipasang menghadap matahari. 2. Sel surya menangkap cahaya matahari dan mengubahnya menjadi listrik. 3. Jadi panel surya mengubah energi cahaya matahari menjadi energi listrik." },
{ q: "Dinamo pada sepeda mengubah energi .... menjadi energi listrik untuk menyalakan lampu.", options: ["gerak menjadi listrik", "panas menjadi gerak", "cahaya menjadi panas", "kimia menjadi gerak"], answer: 0, solution: "1. Dinamo menempel pada roda sepeda yang berputar. 2. Putaran roda (energi gerak) memutar dinamo hingga menghasilkan listrik. 3. Jadi dinamo mengubah energi gerak menjadi energi listrik." },
{ q: "Saat gendang ditabuh, perubahan energi yang terjadi adalah ....", options: ["bunyi menjadi gerak", "gerak menjadi bunyi", "panas menjadi bunyi", "listrik menjadi gerak"], answer: 1, solution: "1. Tangan yang menabuh bergerak dan mengenai permukaan gendang. 2. Getaran permukaan gendang menghasilkan bunyi. 3. Jadi perubahannya adalah energi gerak menjadi energi bunyi." },
{ q: "Kompor gas yang menyala mengubah energi .... menjadi energi panas.", options: ["listrik", "gerak", "kimia", "bunyi"], answer: 2, solution: "1. Gas LPG mengandung energi kimia dari bahan bakar. 2. Saat dibakar, energi kimia berubah menjadi panas untuk memasak. 3. Jadi kompor gas mengubah energi kimia menjadi energi panas." },
{ q: "Mobil yang melaju mengubah energi kimia dari bensin menjadi energi ....", options: ["gerak dan panas", "cahaya dan bunyi", "listrik dan kimia", "panas saja"], answer: 0, solution: "1. Bensin dibakar di dalam mesin mobil. 2. Hasil pembakaran menggerakkan mesin (energi gerak) dan mesin ikut menjadi panas. 3. Jadi mobil mengubah energi kimia menjadi energi gerak dan panas." },
{ q: "Energi bunyi dihasilkan oleh ....", options: ["benda yang bergetar", "benda yang diam", "benda yang dingin", "benda yang gelap"], answer: 0, solution: "1. Bunyi terjadi ketika ada benda yang bergetar. 2. Contohnya senar gitar yang dipetik bergetar lalu terdengar bunyi. 3. Jadi energi bunyi dihasilkan oleh benda yang bergetar." },
{ q: "Api unggun yang menyala menghasilkan energi ....", options: ["panas dan cahaya", "gerak dan bunyi", "listrik dan kimia", "kimia saja"], answer: 0, solution: "1. Api unggun berasal dari kayu yang dibakar. 2. Pembakaran menghasilkan rasa hangat (energi panas) dan nyala yang terlihat (energi cahaya). 3. Jadi api unggun menghasilkan energi panas dan cahaya." },
{ q: "Pembangkit listrik tenaga bayu (PLTB) memanfaatkan energi ....", options: ["air", "angin", "matahari", "panas bumi"], answer: 1, solution: "1. PLTB menggunakan kincir angin yang besar. 2. Tiupan angin memutar kincir dan putarannya diubah menjadi listrik. 3. Jadi PLTB memanfaatkan energi angin." },
{ q: "Kincir air yang berputar di sungai memanfaatkan energi ....", options: ["panas air", "gerak air", "cahaya air", "kimia air"], answer: 1, solution: "1. Air sungai yang mengalir mendorong kincir air. 2. Dorongan aliran air membuat kincir berputar, artinya energi gerak air dipakai. 3. Jadi kincir air memanfaatkan energi gerak air." },
{ q: "Pembangkit listrik yang memanfaatkan panas dari dalam bumi disebut pembangkit listrik tenaga ....", options: ["air", "angin", "panas bumi", "surya"], answer: 2, solution: "1. Di dalam bumi tersimpan panas alami (geotermal). 2. Panas ini dipakai untuk menghasilkan uap yang memutar turbin listrik. 3. Jadi pembangkitnya disebut pembangkit listrik tenaga panas bumi." },
{ q: "Bensin dan batu bara disebut bahan bakar fosil karena ....", options: ["berasal dari fosil sisa makhluk hidup jutaan tahun lalu", "dibuat dari batu gunung", "berasal dari air hujan", "dibuat di pabrik dari plastik"], answer: 0, solution: "1. Bensin dan batu bara berasal dari minyak bumi dan tumbuhan purba. 2. Sisa makhluk hidup itu tertimbun dan berubah selama jutaan tahun menjadi bahan bakar. 3. Karena berasal dari fosil, keduanya disebut bahan bakar fosil." },
{ q: "Tubuh kita memperoleh energi untuk beraktivitas sehari-hari dari ....", options: ["air putih", "makanan", "udara", "pakaian"], answer: 1, solution: "1. Makanan mengandung energi kimia. 2. Tubuh mengolah makanan menjadi energi untuk bergerak, belajar, dan bermain. 3. Jadi energi tubuh berasal dari makanan." },
{ q: "Baterai pada mobil mainan menyimpan energi dalam bentuk energi ....", options: ["gerak", "kimia", "bunyi", "panas"], answer: 1, solution: "1. Baterai menyimpan energi sebelum dipakai. 2. Energi yang tersimpan di dalam baterai adalah energi kimia. 3. Jadi baterai menyimpan energi kimia." },
{ q: "Kalkulator bertenaga surya mengubah energi cahaya menjadi energi ....", options: ["listrik", "panas", "gerak", "kimia"], answer: 0, solution: "1. Kalkulator surya memiliki panel kecil penangkap cahaya. 2. Cahaya yang ditangkap diubah menjadi listrik untuk menghidupkan kalkulator. 3. Jadi perubahannya adalah energi cahaya menjadi energi listrik." },
{ q: "Kedua telapak tangan yang digosok-gosokkan menjadi hangat karena terjadi perubahan energi ....", options: ["panas menjadi gerak", "gerak menjadi panas", "cahaya menjadi panas", "kimia menjadi gerak"], answer: 1, solution: "1. Tangan yang digosok bergerak saling bergesekan. 2. Gesekan mengubah energi gerak menjadi energi panas. 3. Jadi telapak tangan menjadi hangat karena perubahan energi gerak menjadi panas." },
{ q: "Bor listrik mengubah energi listrik menjadi energi ....", options: ["panas", "gerak", "cahaya", "kimia"], answer: 1, solution: "1. Bor listrik memiliki motor di dalamnya. 2. Motor mengubah listrik menjadi putaran mata bor, yaitu energi gerak. 3. Jadi bor listrik mengubah energi listrik menjadi energi gerak." },
{ q: "Pengeras suara (speaker) mengubah energi listrik menjadi energi ....", options: ["bunyi", "panas", "cahaya", "gerak"], answer: 0, solution: "1. Speaker menerima sinyal listrik dari radio atau HP. 2. Sinyal listrik menggetarkan membran speaker hingga terdengar suara. 3. Jadi speaker mengubah energi listrik menjadi energi bunyi." },
{ q: "Energi yang tidak akan habis meskipun digunakan terus-menerus disebut energi ....", options: ["fosil", "terbarukan", "kimia", "buatan"], answer: 1, solution: "1. Energi matahari, angin, dan air selalu tersedia di alam. 2. Energi yang terus tersedia dan dapat dipakai berulang disebut energi terbarukan. 3. Jadi jawabannya adalah energi terbarukan." },
{ q: "Air panas memiliki energi panas yang .... dibandingkan air dingin dalam jumlah yang sama.", options: ["lebih kecil", "lebih besar", "sama besar", "hilang"], answer: 1, solution: "1. Energi panas berkaitan dengan suhu benda. 2. Semakin tinggi suhu benda, semakin besar energi panas yang dimilikinya. 3. Jadi air panas memiliki energi panas lebih besar daripada air dingin." },
{ q: "Lilin yang menyala mengubah energi kimia menjadi energi ....", options: ["cahaya dan panas", "gerak dan bunyi", "listrik dan gerak", "kimia dan gerak"], answer: 0, solution: "1. Lilin mengandung bahan bakar yang menyimpan energi kimia. 2. Saat sumbu dibakar, muncul nyala (cahaya) yang terasa hangat (panas). 3. Jadi lilin mengubah energi kimia menjadi cahaya dan panas." },
{ q: "Bola yang dilempar ke atas, saat mencapai titik tertinggi memiliki energi .... yang paling besar.", options: ["kinetik", "potensial", "bunyi", "listrik"], answer: 1, solution: "1. Saat naik, kecepatan bola berkurang sehingga energi kinetiknya mengecil. 2. Energi gerak itu berubah menjadi energi potensial karena kedudukannya makin tinggi. 3. Jadi di titik tertinggi energi potensialnya paling besar." },
{ q: "Jungkat-jungkit termasuk pesawat sederhana jenis ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 0, solution: "1. Jungkat-jungkit memiliki batang yang berputar pada titik tumpu di tengahnya. 2. Alat yang bekerja dengan batang dan titik tumpu disebut tuas. 3. Jadi jungkat-jungkit termasuk tuas." },
{ q: "Pada gunting, bagian yang menjadi titik tumpu adalah ....", options: ["ujung gagang", "mata pisau", "baut di tengah", "ujung tajam"], answer: 2, solution: "1. Gunting bekerja seperti tuas dengan dua batang. 2. Kedua batang gunting berputar pada baut yang ada di tengahnya. 3. Jadi titik tumpu gunting adalah baut di tengah." },
{ q: "Pembuka tutup botol memudahkan membuka botol karena bekerja dengan prinsip ....", options: ["katrol", "bidang miring", "tuas", "roda berporos"], answer: 2, solution: "1. Pembuka tutup botol mencongkel tutup dengan cara diungkit. 2. Alat yang mengungkit beban dengan titik tumpu disebut tuas. 3. Jadi pembuka tutup botol bekerja dengan prinsip tuas." },
{ q: "Gerobak dorong untuk mengangkut pasir menggunakan prinsip ....", options: ["tuas", "katrol", "bidang miring", "gaya magnet"], answer: 0, solution: "1. Gerobak dorong diangkat pada gagangnya dengan roda sebagai titik tumpu. 2. Cara kerja seperti ini sama dengan tuas. 3. Jadi gerobak dorong menggunakan prinsip tuas." },
{ q: "Linggis dapat mencabut paku dengan mudah karena bekerja seperti ....", options: ["katrol", "tuas", "bidang miring", "roda berporos"], answer: 1, solution: "1. Linggis mencongkel paku dengan salah satu ujungnya menempel sebagai titik tumpu. 2. Alat pengungkit dengan titik tumpu disebut tuas. 3. Jadi linggis bekerja seperti tuas." },
{ q: "Katrol pada tiang bendera berfungsi untuk ....", options: ["memperbesar bendera", "mengubah arah gaya tarikan", "menambah berat bendera", "mempercepat angin"], answer: 1, solution: "1. Tali bendera dipasang melewati katrol di ujung tiang. 2. Saat tali ditarik ke bawah, bendera justru naik ke atas. 3. Jadi katrol berfungsi mengubah arah gaya tarikan." },
{ q: "Derek di proyek bangunan menggunakan katrol dengan tujuan ....", options: ["mengangkat beban berat ke tempat tinggi", "menurunkan kecepatan angin", "memperindah bangunan", "menghemat bahan bangunan"], answer: 0, solution: "1. Derek harus memindahkan material berat ke lantai atas gedung. 2. Katrol memudahkan menarik tali untuk mengangkat beban berat itu. 3. Jadi derek memakai katrol untuk mengangkat beban berat ke tempat tinggi." },
{ q: "Dibandingkan mengangkat langsung, mengangkat beban dengan katrol bergerak membutuhkan gaya yang ....", options: ["lebih besar", "sama besar", "lebih kecil", "berubah-ubah"], answer: 2, solution: "1. Katrol bergerak ikut naik bersama beban yang diangkat. 2. Beban ditopang oleh dua tali sehingga gaya yang diperlukan menjadi lebih kecil. 3. Jadi gaya yang dibutuhkan lebih kecil." },
{ q: "Papan yang disandarkan dari tanah ke bak truk untuk menaikkan drum merupakan penerapan ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 2, solution: "1. Papan miring menghubungkan tempat rendah ke tempat tinggi. 2. Permukaan miring yang memudahkan memindahkan benda ke atas disebut bidang miring. 3. Jadi papan itu merupakan penerapan bidang miring." },
{ q: "Perosotan di taman bermain menerapkan prinsip pesawat sederhana berupa ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 2, solution: "1. Perosotan adalah permukaan miring dari atas ke bawah. 2. Permukaan miring termasuk pesawat sederhana bidang miring. 3. Jadi perosotan menerapkan prinsip bidang miring." },
{ q: "Kapak dapat membelah kayu dengan mudah karena mata kapak berbentuk ....", options: ["tuas", "katrol ganda", "bidang miring", "roda berporos"], answer: 2, solution: "1. Mata kapak yang tajam berbentuk dua sisi miring (baji). 2. Baji merupakan bentuk penerapan bidang miring. 3. Jadi kapak bekerja dengan prinsip bidang miring." },
{ q: "Roda sepeda termasuk pesawat sederhana jenis ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 3, solution: "1. Roda sepeda berputar pada poros (as) di tengahnya. 2. Alat berupa roda yang berputar pada poros disebut roda berporos. 3. Jadi roda sepeda termasuk roda berporos." },
{ q: "Setir mobil yang diputar pengemudi bekerja dengan prinsip ....", options: ["roda berporos", "katrol tetap", "tuas jenis tiga", "bidang miring"], answer: 0, solution: "1. Setir mobil berbentuk lingkaran yang diputar. 2. Putaran setir diteruskan ke poros kemudi untuk membelokkan roda. 3. Jadi setir mobil bekerja dengan prinsip roda berporos." },
{ q: "Gagang pintu yang diputar untuk membuka pintu termasuk pesawat sederhana ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 3, solution: "1. Gagang pintu yang bulat diputar seperti roda. 2. Putarannya diteruskan ke poros pengunci pintu. 3. Jadi gagang pintu termasuk roda berporos." },
{ q: "Kincir air yang berputar pada asnya untuk menumbuk padi termasuk ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 3, solution: "1. Kincir air berbentuk lingkaran besar yang berputar. 2. Kincir berputar pada as (poros) di tengahnya. 3. Jadi kincir air termasuk roda berporos." },
{ q: "Sekop yang dipakai untuk menyendok pasir bekerja dengan prinsip ....", options: ["katrol", "tuas", "bidang miring", "roda berporos"], answer: 1, solution: "1. Sekop dipegang dengan dua tangan dan ujungnya mengangkat pasir. 2. Cara mengangkat dengan mengungkit seperti ini termasuk tuas. 3. Jadi sekop bekerja dengan prinsip tuas." },
{ q: "Pinset yang dipakai untuk mencabut duri bekerja dengan prinsip ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 0, solution: "1. Pinset dijepit dengan jari sehingga ujungnya menutup. 2. Gerakan menjepit dengan titik tekuk di pangkalnya termasuk tuas. 3. Jadi pinset bekerja dengan prinsip tuas." },
{ q: "Untuk menaikkan drum yang berat ke atas truk, papan landai lebih dipilih daripada papan curam karena gaya yang diperlukan ....", options: ["lebih besar", "lebih kecil", "sama saja", "tidak ada"], answer: 1, solution: "1. Bidang miring yang landai menempuh jarak lebih jauh. 2. Semakin landai bidang miring, semakin kecil gaya yang diperlukan. 3. Jadi papan landai membutuhkan gaya yang lebih kecil." },
{ q: "Menimba air dengan katrol tetap terasa ringan karena ....", options: ["air menjadi ringan", "gaya tarik ke bawah dibantu berat badan", "katrol menambah air", "tali menjadi kuat"], answer: 1, solution: "1. Katrol tetap mengubah arah gaya, bukan memperkecil gaya. 2. Penimba menarik tali ke bawah sehingga berat badannya ikut membantu. 3. Jadi menimba terasa ringan karena gaya tarik ke bawah dibantu berat badan." },
{ q: "Obeng yang dipakai untuk memutar sekrup bekerja seperti ....", options: ["tuas", "katrol", "bidang miring", "roda berporos"], answer: 3, solution: "1. Gagang obeng yang bulat diputar oleh tangan. 2. Putaran gagang diteruskan ke batang obeng sebagai porosnya. 3. Jadi obeng bekerja seperti roda berporos." },
{ q: "Plastisin yang ditekan dengan jari berubah bentuk. Hal ini menunjukkan gaya dapat ....", options: ["mengubah bentuk benda", "mengubah warna benda", "menambah berat benda", "menghilangkan benda"], answer: 0, solution: "1. Plastisin mula-mula berbentuk bulat lalu ditekan. 2. Setelah ditekan bentuknya berubah menjadi pipih. 3. Jadi gaya dapat mengubah bentuk benda." },
{ q: "Bola yang ditendang ke arah gawang berbelok setelah mengenai pemain lawan. Hal ini menunjukkan gaya dapat ....", options: ["mengubah arah gerak benda", "mengubah warna benda", "menambah besar benda", "menghentikan waktu"], answer: 0, solution: "1. Bola semula bergerak lurus ke gawang. 2. Setelah terkena pemain, arah gerak bola berubah. 3. Jadi gaya dapat mengubah arah gerak benda." },
{ q: "Mobil mainan yang diam lalu didorong menjadi bergerak. Hal ini menunjukkan gaya dapat ....", options: ["menghentikan benda", "membuat benda diam bergerak", "mengubah warna benda", "memperbesar benda"], answer: 1, solution: "1. Mobil mainan awalnya diam tidak bergerak. 2. Setelah didorong (diberi gaya), mobil menjadi bergerak. 3. Jadi gaya dapat membuat benda yang diam menjadi bergerak." },
{ q: "Kiper menangkap bola yang melaju kencang hingga berhenti. Hal ini menunjukkan gaya dapat ....", options: ["mempercepat benda", "menghentikan gerak benda", "mengubah bentuk bola", "menambah berat bola"], answer: 1, solution: "1. Bola yang ditangkap kiper sedang bergerak cepat. 2. Tangan kiper memberi gaya hingga bola berhenti. 3. Jadi gaya dapat menghentikan gerak benda." },
{ q: "Saat mendorong meja, gaya yang digunakan berasal dari ....", options: ["gaya otot", "gaya magnet", "gaya listrik", "gaya gravitasi"], answer: 0, solution: "1. Mendorong meja memakai tenaga tangan dan kaki. 2. Gaya yang berasal dari tenaga makhluk hidup disebut gaya otot. 3. Jadi mendorong meja memakai gaya otot." },
{ q: "Magnet dapat menarik paku dari jarak tertentu tanpa menyentuhnya. Hal ini menunjukkan adanya ....", options: ["gaya otot", "gaya magnet", "gaya gesek", "gaya pegas"], answer: 1, solution: "1. Magnet menarik benda logam seperti paku dan jarum. 2. Tarikan itu terjadi meski tidak bersentuhan langsung. 3. Jadi hal ini menunjukkan adanya gaya magnet." },
{ q: "Bola yang dilempar ke atas selalu jatuh kembali ke tanah karena pengaruh ....", options: ["gaya magnet", "gaya otot", "gaya gravitasi", "gaya gesek"], answer: 2, solution: "1. Semua benda yang dilempar ke atas akan turun lagi. 2. Bumi menarik semua benda ke arahnya, tarikan ini disebut gaya gravitasi. 3. Jadi bola jatuh kembali karena gaya gravitasi." },
{ q: "Arah gaya gravitasi bumi selalu ....", options: ["ke atas", "ke samping", "ke bawah menuju pusat bumi", "menjauhi bumi"], answer: 2, solution: "1. Gaya gravitasi adalah tarikan bumi terhadap benda. 2. Tarikan itu mengarah ke pusat bumi, yaitu ke bawah. 3. Jadi arah gaya gravitasi selalu ke bawah menuju pusat bumi." },
{ q: "Lantai yang licin membuat orang mudah terpeleset karena gaya geseknya ....", options: ["besar", "kecil", "hilang", "berubah arah"], answer: 1, solution: "1. Gaya gesek menahan kaki agar tidak selip. 2. Pada lantai licin, gaya gesek antara kaki dan lantai kecil. 3. Jadi orang mudah terpeleset karena gaya geseknya kecil." },
{ q: "Sepatu pemain bola memakai pul (tonjolan) pada solnya dengan tujuan ....", options: ["agar terlihat bagus", "menambah gaya gesek agar tidak terpeleset", "mengurangi berat badan", "menambah kecepatan lari"], answer: 1, solution: "1. Lapangan bola sering licin terutama saat basah. 2. Pul pada sepatu mencengkeram tanah sehingga gaya gesek bertambah. 3. Jadi tujuannya menambah gaya gesek agar tidak terpeleset." },
{ q: "Rem sepeda dapat menghentikan putaran roda karena ....", options: ["adanya gaya gesek antara rem dan roda", "roda menjadi ringan", "adanya gaya magnet", "ban menjadi panas"], answer: 0, solution: "1. Saat tuas rem ditarik, kampas rem menjepit roda. 2. Jepitan itu menimbulkan gaya gesek yang menahan putaran roda. 3. Jadi rem menghentikan roda karena gaya gesek." },
{ q: "Rantai sepeda diberi minyak pelumas dengan tujuan ....", options: ["menambah gaya gesek", "mengurangi gaya gesek", "menambah berat rantai", "mengubah warna rantai"], answer: 1, solution: "1. Gesekan pada rantai membuat kayuhan berat dan rantai cepat aus. 2. Minyak pelumas membuat permukaan licin sehingga gesekan berkurang. 3. Jadi tujuannya mengurangi gaya gesek." },
{ q: "Sebuah mobil melaju dengan kecepatan 60 km/jam selama 2 jam. Jarak yang ditempuh mobil adalah ....", options: ["30 km", "60 km", "120 km", "240 km"], answer: 2, solution: "1. Jarak dihitung dengan kecepatan dikali waktu. 2. 60 km/jam dikali 2 jam sama dengan 120 km. 3. Jadi jarak yang ditempuh adalah 120 km." },
{ q: "Sebuah benda dikatakan bergerak jika ....", options: ["warnanya berubah", "kedudukannya berubah terhadap titik acuan", "bentuknya berubah", "suhunya berubah"], answer: 1, solution: "1. Gerak selalu dilihat dari titik acuan, misalnya pohon di pinggir jalan. 2. Jika kedudukan benda berubah terhadap titik acuan, benda itu bergerak. 3. Jadi benda dikatakan bergerak jika kedudukannya berubah terhadap titik acuan." },
{ q: "Budi berlari sejauh 100 meter dalam waktu 20 detik. Kecepatan lari Budi adalah ....", options: ["2 m/s", "5 m/s", "20 m/s", "2000 m/s"], answer: 1, solution: "1. Kecepatan dihitung dengan jarak dibagi waktu. 2. 100 meter dibagi 20 detik sama dengan 5 m/s. 3. Jadi kecepatan lari Budi adalah 5 m/s." },
{ q: "Sepeda yang dikayuh semakin cepat menunjukkan bahwa gaya dapat ....", options: ["menghentikan benda", "mengubah kecepatan benda", "mengubah warna benda", "mengurangi berat benda"], answer: 1, solution: "1. Kayuhan memberi gaya dorong pada sepeda. 2. Semakin kuat dikayuh, kecepatan sepeda bertambah. 3. Jadi gaya dapat mengubah kecepatan benda." },
{ q: "Ketapel dapat melontarkan batu dengan jauh karena menggunakan ....", options: ["gaya otot", "gaya pegas karet", "gaya magnet", "gaya listrik"], answer: 1, solution: "1. Karet ketapel direntangkan lalu dilepaskan. 2. Karet yang kembali ke bentuk semula memberi dorongan kuat, yaitu gaya pegas. 3. Jadi ketapel melontarkan batu karena gaya pegas karet." },
{ q: "Penggaris plastik yang digosokkan ke rambut kering dapat menarik potongan kertas kecil karena adanya ....", options: ["gaya magnet", "gaya otot", "gaya listrik", "gaya gravitasi"], answer: 2, solution: "1. Gosokan pada rambut membuat penggaris bermuatan listrik. 2. Muatan listrik itu menarik benda ringan seperti potongan kertas. 3. Jadi hal ini terjadi karena gaya listrik." },
{ q: "Dua kutub magnet yang sama (utara dengan utara) didekatkan akan ....", options: ["saling menarik", "saling menolak", "menempel kuat", "tidak terjadi apa-apa"], answer: 1, solution: "1. Magnet memiliki kutub utara dan kutub selatan. 2. Kutub yang sama akan saling menolak, kutub berbeda saling menarik. 3. Jadi utara dengan utara akan saling menolak." },
{ q: "Perahu layar dapat bergerak di laut karena didorong oleh ....", options: ["gaya otot pendayung", "gaya angin pada layar", "gaya magnet bumi", "gaya listrik"], answer: 1, solution: "1. Perahu layar memiliki layar lebar penangkap angin. 2. Angin yang bertiup menekan layar sehingga perahu terdorong maju. 3. Jadi perahu layar bergerak karena gaya angin pada layar." },
{ q: "Penerjun payung dapat mendarat dengan pelan karena ....", options: ["payung menambah berat badan", "udara menahan payung (gaya gesek udara)", "gravitasi berkurang", "angin berhenti bertiup"], answer: 1, solution: "1. Payung yang mengembang memiliki permukaan lebar. 2. Udara menahan permukaan payung sehingga kecepatan jatuh berkurang. 3. Jadi penerjun mendarat pelan karena udara menahan payung." },
{ q: "Astronot di bulan dapat melompat lebih tinggi daripada di bumi karena ....", options: ["bulan tidak punya udara", "gravitasi bulan lebih kecil", "bulan lebih dekat ke matahari", "astronot lebih kuat"], answer: 1, solution: "1. Gaya gravitasi bulan lebih kecil daripada gravitasi bumi. 2. Tarikan yang kecil membuat lompatan astronot lebih tinggi. 3. Jadi astronot melompat tinggi karena gravitasi bulan lebih kecil." },
{ q: "Daun kering yang jatuh dari pohon melayang-layang di udara karena ....", options: ["mendapat hambatan dari udara", "ditarik magnet bumi", "daun sangat berat", "tidak ada gravitasi"], answer: 0, solution: "1. Daun kering ringan dan permukaannya lebar. 2. Udara menahan daun yang jatuh sehingga geraknya melayang-layang. 3. Jadi daun melayang karena mendapat hambatan dari udara." },
{ q: "Untuk menghentikan bola yang menggelinding cepat diperlukan gaya yang .... dibandingkan bola yang menggelinding pelan.", options: ["lebih kecil", "lebih besar", "sama besar", "tidak perlu"], answer: 1, solution: "1. Bola yang cepat memiliki gerak yang lebih kuat. 2. Semakin cepat gerak benda, semakin besar gaya yang dibutuhkan untuk menghentikannya. 3. Jadi diperlukan gaya yang lebih besar." },
{ q: "Mobil mainan yang didorong berhenti lebih cepat di lantai kasar daripada di lantai licin karena ....", options: ["lantai kasar menambah kecepatan", "gaya gesek lantai kasar lebih besar", "lantai licin menarik mobil", "gravitasi di lantai kasar lebih besar"], answer: 1, solution: "1. Permukaan kasar menimbulkan gesekan lebih besar dengan roda mobil. 2. Gesekan yang besar lebih cepat menghentikan gerak mobil. 3. Jadi mobil berhenti lebih cepat karena gaya gesek lantai kasar lebih besar." },
{ q: "Planet kedua dari matahari adalah ....", options: ["Merkurius", "Venus", "Bumi", "Mars"], answer: 1, solution: "1. Urutan planet dari matahari adalah Merkurius, Venus, Bumi, Mars, dan seterusnya. 2. Planet pertama adalah Merkurius. 3. Jadi planet kedua adalah Venus." },
{ q: "Planet terbesar dalam tata surya adalah ....", options: ["Saturnus", "Bumi", "Jupiter", "Neptunus"], answer: 2, solution: "1. Planet-planet memiliki ukuran yang berbeda-beda. 2. Jupiter berukuran paling besar di antara semua planet. 3. Jadi planet terbesar adalah Jupiter." },
{ q: "Planet yang dijuluki planet merah adalah ....", options: ["Venus", "Mars", "Jupiter", "Merkurius"], answer: 1, solution: "1. Permukaan Mars banyak mengandung debu berwarna kemerahan. 2. Warna merah itu terlihat jelas dari bumi. 3. Jadi Mars dijuluki planet merah." },
{ q: "Planet yang memiliki cincin indah yang terlihat jelas adalah ....", options: ["Mars", "Venus", "Saturnus", "Merkurius"], answer: 2, solution: "1. Beberapa planet memiliki cincin, tetapi cincin Saturnus paling jelas terlihat. 2. Cincin itu terbuat dari jutaan bongkahan es dan batuan. 3. Jadi planet bercincin indah itu adalah Saturnus." },
{ q: "Planet yang paling jauh dari matahari adalah ....", options: ["Uranus", "Saturnus", "Jupiter", "Neptunus"], answer: 3, solution: "1. Planet kedelapan atau terakhir dalam tata surya letaknya paling jauh. 2. Setelah Uranus, planet terakhir adalah Neptunus. 3. Jadi planet terjauh dari matahari adalah Neptunus." },
{ q: "Planet tempat manusia dan makhluk hidup lainnya tinggal adalah ....", options: ["Mars", "Venus", "Bumi", "Bulan"], answer: 2, solution: "1. Makhluk hidup membutuhkan air, udara, dan suhu yang sesuai. 2. Di antara semua planet, hanya Bumi yang memiliki ketiganya. 3. Jadi planet tempat tinggal makhluk hidup adalah Bumi." },
{ q: "Waktu yang dibutuhkan bumi untuk satu kali mengelilingi matahari (revolusi) adalah ....", options: ["24 jam", "30 hari", "365 hari", "12 jam"], answer: 2, solution: "1. Bumi mengelilingi matahari dalam orbitnya. 2. Satu putaran penuh membutuhkan waktu sekitar 365 hari. 3. Jadi satu kali revolusi bumi adalah 365 hari." },
{ q: "Waktu yang dibutuhkan bumi untuk satu kali berputar pada porosnya (rotasi) adalah ....", options: ["12 jam", "24 jam", "30 hari", "365 hari"], answer: 1, solution: "1. Bumi berputar pada porosnya dari barat ke timur. 2. Satu putaran penuh membutuhkan waktu 24 jam. 3. Jadi satu kali rotasi bumi adalah 24 jam." },
{ q: "Matahari tampak terbit di timur dan tenggelam di barat setiap hari. Peristiwa ini disebut gerak semu harian matahari yang disebabkan oleh ....", options: ["revolusi bumi", "rotasi bumi", "revolusi bulan", "gravitasi matahari"], answer: 1, solution: "1. Sebenarnya matahari tidak bergerak mengelilingi bumi. 2. Bumi berputar pada porosnya sehingga matahari tampak bergerak. 3. Jadi gerak semu harian matahari disebabkan rotasi bumi." },
{ q: "Tahun kabisat memiliki jumlah hari sebanyak ....", options: ["364 hari", "365 hari", "366 hari", "367 hari"], answer: 2, solution: "1. Bumi berevolusi selama 365 seperempat hari setiap tahun. 2. Kelebihan seperempat hari dikumpulkan setiap 4 tahun menjadi 1 hari tambahan di bulan Februari. 3. Jadi tahun kabisat berjumlah 366 hari." },
{ q: "Gerhana bulan terjadi ketika ....", options: ["bulan berada di antara matahari dan bumi", "bumi berada di antara matahari dan bulan", "matahari berada di antara bumi dan bulan", "bulan menutupi matahari"], answer: 1, solution: "1. Gerhana bulan terjadi saat bayangan bumi jatuh ke bulan. 2. Hal ini hanya bisa terjadi jika bumi berada di antara matahari dan bulan. 3. Jadi gerhana bulan terjadi ketika bumi berada di antara matahari dan bulan." },
{ q: "Saat terjadi gerhana matahari, urutan benda langit dari matahari adalah ....", options: ["matahari - bumi - bulan", "matahari - bulan - bumi", "bulan - matahari - bumi", "bumi - matahari - bulan"], answer: 1, solution: "1. Gerhana matahari terjadi karena bulan menutupi matahari. 2. Agar tertutup, bulan harus berada di antara matahari dan bumi. 3. Jadi urutannya adalah matahari - bulan - bumi." },
{ q: "Fase bulan baru (bulan mati) terjadi ketika posisi bulan ....", options: ["di belakang bumi", "di antara matahari dan bumi", "di belakang matahari", "sejajar di samping bumi"], answer: 1, solution: "1. Pada fase bulan baru, sisi bulan yang menghadap bumi tidak terkena cahaya matahari. 2. Hal ini terjadi saat bulan berada di antara matahari dan bumi. 3. Jadi bulan baru terjadi ketika bulan di antara matahari dan bumi." },
{ q: "Bulan tampak bercahaya di malam hari padahal bulan ....", options: ["memiliki cahaya sendiri", "memantulkan cahaya matahari", "membakar gas seperti bintang", "menangkap cahaya bintang"], answer: 1, solution: "1. Bulan adalah benda langit berbatu yang tidak bisa menghasilkan cahaya. 2. Cahaya bulan yang kita lihat berasal dari pantulan cahaya matahari. 3. Jadi bulan bercahaya karena memantulkan cahaya matahari." },
{ q: "Permukaan bulan banyak terdapat kawah (lubang besar) yang terbentuk karena ....", options: ["letusan gunung berapi", "hantaman meteor", "galian manusia", "tiupan angin kencang"], answer: 1, solution: "1. Bulan tidak memiliki udara pelindung seperti bumi. 2. Meteor yang jatuh langsung menghantam permukaan dan membentuk kawah. 3. Jadi kawah bulan terbentuk karena hantaman meteor." },
{ q: "Bintang yang paling dekat dengan bumi adalah ....", options: ["Bintang Utara", "matahari", "Bintang Kejora", "Bintang Sirius"], answer: 1, solution: "1. Bintang-bintang di langit malam jaraknya sangat jauh dari bumi. 2. Matahari adalah bintang yang jaraknya paling dekat dengan bumi. 3. Jadi bintang terdekat dari bumi adalah matahari." },
{ q: "Matahari sebenarnya termasuk ....", options: ["planet", "bintang", "bulan", "komet"], answer: 1, solution: "1. Matahari menghasilkan cahaya dan panasnya sendiri. 2. Benda langit yang menghasilkan cahaya sendiri disebut bintang. 3. Jadi matahari termasuk bintang." },
{ q: "Planet-planet selalu mengelilingi matahari dan tidak terlepas karena adanya ....", options: ["gaya magnet bumi", "gaya gravitasi matahari", "dorongan angin", "putaran bulan"], answer: 1, solution: "1. Matahari memiliki massa yang sangat besar. 2. Massa besar menimbulkan gaya gravitasi kuat yang menahan planet-planet pada orbitnya. 3. Jadi planet mengelilingi matahari karena gaya gravitasi matahari." },
{ q: "Palapa adalah contoh satelit ....", options: ["alami milik bumi", "buatan manusia", "alami milik mars", "pecahan komet"], answer: 1, solution: "1. Satelit alami bumi hanyalah bulan. 2. Palapa dibuat dan diluncurkan manusia untuk komunikasi. 3. Jadi Palapa adalah contoh satelit buatan manusia." },
{ q: "Asteroid adalah ....", options: ["bintang berekor", "batuan kecil yang mengelilingi matahari", "planet yang bercahaya", "satelit buatan"], answer: 1, solution: "1. Di antara orbit Mars dan Jupiter terdapat jutaan batuan kecil. 2. Batuan-batuan kecil yang mengelilingi matahari itu disebut asteroid. 3. Jadi asteroid adalah batuan kecil yang mengelilingi matahari." },
{ q: "Perhatikan rantai makanan berikut: rumput → rusa → serigala. Rusa berperan sebagai ...", options: ["produsen", "konsumen tingkat I", "konsumen tingkat II", "pengurai"], answer: 1, solution: "1. Rumput adalah tumbuhan hijau yang membuat makanannya sendiri, jadi produsen. 2. Rusa memakan rumput (tumbuhan), sehingga rusa adalah konsumen tingkat I atau herbivora. 3. Serigala memakan rusa, jadi konsumen tingkat II." },
{ q: "Jamur yang tumbuh pada kayu lapuk memperoleh makanan dengan menguraikan sisa makhluk hidup. Peran jamur dalam rantai makanan adalah sebagai ...", options: ["konsumen tingkat I", "pengurai", "konsumen puncak", "produsen"], answer: 1, solution: "1. Jamur tidak bisa membuat makanan sendiri karena tidak berfotosintesis. 2. Jamur memperoleh makanan dari sisa makhluk hidup yang sudah mati, seperti kayu lapuk. 3. Makhluk hidup yang menguraikan sisa makhluk hidup disebut pengurai atau dekomposer." },
{ q: "Perhatikan rantai makanan di laut: fitoplankton → zooplankton → ikan teri → ikan tuna. Yang berperan sebagai konsumen tingkat II adalah ...", options: ["ikan teri", "ikan tuna", "fitoplankton", "zooplankton"], answer: 0, solution: "1. Fitoplankton adalah produsen karena bisa berfotosintesis. 2. Zooplankton memakan fitoplankton, jadi konsumen tingkat I. 3. Ikan teri memakan zooplankton, jadi konsumen tingkat II. 4. Ikan tuna memakan ikan teri, jadi konsumen tingkat III." },
{ q: "Di sebuah sawah, ular banyak ditangkap manusia. Akibat yang paling mungkin terjadi pada ekosistem sawah tersebut adalah ...", options: ["katak berubah menjadi herbivora", "tanaman padi tumbuh semakin subur", "populasi tikus meningkat sehingga padi rusak", "populasi elang bertambah banyak"], answer: 2, solution: "1. Dalam rantai makanan sawah, ular adalah pemangsa tikus. 2. Jika ular berkurang, tidak ada yang memangsa tikus sehingga populasi tikus meledak. 3. Tikus yang banyak akan memakan banyak tanaman padi sehingga padi rusak dan petani merugi." },
{ q: "Jaring-jaring makanan lebih lengkap daripada rantai makanan karena ...", options: ["hanya memiliki satu produsen", "menggambarkan banyak rantai makanan yang saling berhubungan", "tidak melibatkan pengurai", "hanya terjadi di laut"], answer: 1, solution: "1. Rantai makanan hanya menunjukkan satu jalur makan-dimakan. 2. Di alam, satu hewan bisa memakan banyak jenis makanan dan dimakan banyak pemangsa. 3. Jaring-jaring makanan menggambarkan semua rantai makanan yang saling berhubungan dan tumpang tindih." },
{ q: "Benalu menempel pada pohon mangga dan menyerap air serta zat hara dari pohon tersebut sehingga pohon mangga merugi. Hubungan ini disebut simbiosis ...", options: ["komensalisme", "parasitisme", "netralisme", "mutualisme"], answer: 1, solution: "1. Benalu diuntungkan karena mendapat air dan zat hara dari pohon mangga. 2. Pohon mangga dirugikan karena zat haranya diambil benalu. 3. Hubungan yang menguntungkan satu pihak dan merugikan pihak lain disebut simbiosis parasitisme." },
{ q: "Ikan remora menempel pada tubuh ikan hiu untuk ikut berenang dan memakan sisa makanan hiu, sedangkan hiu tidak dirugikan maupun diuntungkan. Hubungan ini disebut simbiosis ...", options: ["kompetisi", "komensalisme", "mutualisme", "parasitisme"], answer: 1, solution: "1. Ikan remora diuntungkan karena mendapat tumpangan dan sisa makanan. 2. Ikan hiu tidak dirugikan dan tidak diuntungkan oleh kehadiran remora. 3. Hubungan yang menguntungkan satu pihak tanpa memengaruhi pihak lain disebut simbiosis komensalisme." },
{ q: "Burung jalak hinggap di punggung kerbau dan memakan kutu yang menempel di kulit kerbau. Hubungan kerbau dan burung jalak disebut simbiosis ... karena ...", options: ["kompetisi, karena berebut makanan", "mutualisme, karena keduanya saling diuntungkan", "parasitisme, karena kutu merugikan kerbau", "komensalisme, karena hanya burung yang untung"], answer: 1, solution: "1. Burung jalak diuntungkan karena mendapat makanan berupa kutu. 2. Kerbau diuntungkan karena kutu yang mengganggu kulitnya dimakan burung jalak. 3. Hubungan yang saling menguntungkan kedua belah pihak disebut simbiosis mutualisme." },
{ q: "Singa dan harimau berebut seekor rusa hasil buruan. Hubungan antara singa dan harimau tersebut termasuk ...", options: ["simbiosis mutualisme", "simbiosis parasitisme", "predasi", "kompetisi"], answer: 3, solution: "1. Singa dan harimau sama-sama menginginkan rusa yang sama. 2. Keduanya bersaing untuk mendapatkan makanan. 3. Hubungan persaingan untuk mendapatkan kebutuhan yang sama disebut kompetisi." },
{ q: "Produsen selalu berada di awal rantai makanan. Hal ini karena produsen ...", options: ["menjadi sumber makanan dan energi bagi makhluk hidup lain", "menguraikan sisa makhluk hidup", "tidak membutuhkan cahaya matahari", "memakan semua jenis hewan"], answer: 0, solution: "1. Produsen adalah tumbuhan hijau yang membuat makanannya sendiri melalui fotosintesis. 2. Energi dari produsen berpindah ke hewan herbivora, lalu ke karnivora. 3. Tanpa produsen, tidak ada makanan bagi konsumen sehingga produsen selalu di awal rantai makanan." },
{ q: "Tanah di hutan tetap subur walaupun tidak pernah dipupuk manusia. Hal ini terjadi karena ...", options: ["hujan selalu turun setiap hari", "hewan tidak buang kotoran di hutan", "daun yang gugur dibiarkan menumpuk", "pengurai mengembalikan zat hara dari sisa makhluk hidup ke tanah"], answer: 3, solution: "1. Daun gugur, ranting, dan bangkai hewan adalah sisa makhluk hidup. 2. Jamur dan bakteri sebagai pengurai menguraikan sisa tersebut menjadi zat hara. 3. Zat hara diserap kembali oleh akar tumbuhan sehingga tanah tetap subur." },
{ q: "Ayam memakan biji-bijian, cacing, dan sisa nasi. Hewan yang memakan tumbuhan sekaligus hewan seperti ayam disebut ...", options: ["insektivora", "herbivora", "karnivora", "omnivora"], answer: 3, solution: "1. Herbivora hanya memakan tumbuhan, karnivora hanya memakan hewan. 2. Ayam memakan biji-bijian (tumbuhan) sekaligus cacing (hewan). 3. Hewan pemakan tumbuhan dan hewan disebut omnivora atau pemakan segala." },
{ q: "Kelompok hewan berikut yang semuanya termasuk herbivora adalah ...", options: ["harimau, singa, dan buaya", "sapi, kambing, dan kelinci", "elang, ular, dan katak", "ayam, tikus, dan beruang"], answer: 1, solution: "1. Herbivora adalah hewan pemakan tumbuhan. 2. Sapi memakan rumput, kambing memakan daun, kelinci memakan wortel dan sayuran. 3. Harimau, singa, elang, dan ular adalah karnivora, sedangkan ayam dan tikus adalah omnivora." },
{ q: "Elang dalam rantai makanan sering disebut konsumen puncak karena ...", options: ["tidak dimangsa oleh hewan lain", "hidupnya paling lama", "ukurannya paling besar", "memakan produsen secara langsung"], answer: 0, solution: "1. Elang berada di ujung rantai makanan dan memakan ular atau hewan lain. 2. Tidak ada hewan yang memangsa elang di alam. 3. Hewan yang tidak dimangsa hewan lain disebut konsumen puncak." },
{ q: "Tali putri melilit batang tanaman beluntas dan mengisap sari makanan dari tanaman tersebut hingga beluntas layu. Hubungan tali putri dan beluntas termasuk simbiosis ...", options: ["parasitisme", "predasi", "mutualisme", "komensalisme"], answer: 0, solution: "1. Tali putri diuntungkan karena mendapat sari makanan dari beluntas. 2. Beluntas dirugikan karena makanannya diambil hingga layu. 3. Hubungan untung-rugi seperti ini disebut simbiosis parasitisme." },
{ q: "Bunga anggrek menempel pada batang pohon untuk mendapatkan cahaya matahari, sedangkan pohon tidak dirugikan maupun diuntungkan. Hubungan anggrek dan pohon termasuk simbiosis ...", options: ["kompetisi", "parasitisme", "mutualisme", "komensalisme"], answer: 3, solution: "1. Anggrek diuntungkan karena mendapat tempat menempel dan cahaya matahari. 2. Pohon tidak dirugikan karena anggrek tidak mengambil makanan dari pohon. 3. Hubungan yang hanya menguntungkan satu pihak tanpa merugikan pihak lain disebut komensalisme." },
{ q: "Bakteri Rhizobium hidup di akar tanaman kacang-kacangan. Bakteri mendapat tempat tinggal, sedangkan tanaman mendapat nitrogen dari bakteri. Hubungan keduanya termasuk simbiosis ...", options: ["mutualisme", "parasitisme", "komensalisme", "predasi"], answer: 0, solution: "1. Bakteri Rhizobium diuntungkan karena mendapat tempat hidup di akar. 2. Tanaman kacang diuntungkan karena mendapat nitrogen yang menyuburkan. 3. Karena keduanya saling diuntungkan, hubungan ini disebut simbiosis mutualisme." },
{ q: "Hubungan antara kucing dan tikus, di mana kucing memangsa tikus, disebut ...", options: ["kompetisi", "predasi", "simbiosis komensalisme", "simbiosis mutualisme"], answer: 1, solution: "1. Kucing berperan sebagai pemangsa yang memburu tikus. 2. Tikus berperan sebagai mangsa yang dimakan kucing. 3. Hubungan antara pemangsa dan mangsa disebut predasi." },
{ q: "Di ekosistem sawah, berikut ini yang termasuk komponen abiotik adalah ...", options: ["ular, elang, dan belalang", "jamur, bakteri, dan cacing", "padi, tikus, dan katak", "air, tanah, dan cahaya matahari"], answer: 3, solution: "1. Komponen ekosistem terdiri dari biotik (makhluk hidup) dan abiotik (benda tak hidup). 2. Padi, tikus, katak, ular, dan jamur adalah makhluk hidup atau biotik. 3. Air, tanah, dan cahaya matahari adalah benda tak hidup atau abiotik." },
{ q: "Ekosistem dikatakan seimbang apabila ...", options: ["manusia tidak boleh masuk sama sekali", "jumlah hewan lebih banyak dari tumbuhan", "tidak ada populasi makhluk hidup yang meledak atau punah", "hanya ada satu jenis hewan"], answer: 2, solution: "1. Dalam ekosistem, jumlah setiap populasi saling memengaruhi. 2. Jika satu populasi meledak, keseimbangan rantai makanan akan terganggu. 3. Ekosistem seimbang berarti semua populasi dalam jumlah yang wajar dan saling menjaga." },
{ q: "Penebangan hutan secara liar dapat menyebabkan banjir dan tanah longsor. Hal ini karena ...", options: ["pohon ditebang lalu dijual mahal", "tidak ada lagi akar pohon yang menahan air dan tanah", "hewan hutan pindah ke kota", "udara menjadi terlalu panas"], answer: 1, solution: "1. Akar pohon berfungsi menyerap dan menahan air hujan di dalam tanah. 2. Jika pohon ditebang liar, air hujan langsung mengalir di permukaan tanpa tertahan. 3. Aliran air yang deras menyebabkan banjir dan mengikis tanah menjadi longsor." },
{ q: "Perhatikan rantai makanan: bunga → ulat → burung pipit → elang. Yang berperan sebagai konsumen tingkat II adalah ...", options: ["ulat", "burung pipit", "elang", "bunga"], answer: 1, solution: "1. Bunga adalah produsen karena membuat makanan sendiri. 2. Ulat memakan bunga, jadi konsumen tingkat I. 3. Burung pipit memakan ulat, jadi konsumen tingkat II. 4. Elang memakan burung pipit, jadi konsumen tingkat III." },
{ q: "Daun kering yang jatuh ke tanah dimakan rayap, kemudian rayap dimakan katak. Rantai makanan yang diawali dari sisa makhluk hidup seperti ini disebut rantai makanan ...", options: ["parasit", "tumbuhan", "pemangsa", "perombak"], answer: 3, solution: "1. Daun kering adalah sisa makhluk hidup yang sudah mati. 2. Rantai makanan yang diawali dari sisa atau sampah organik disebut rantai perombak atau detritus. 3. Rayap berperan memakan sisa tersebut, lalu dimakan katak." },
{ q: "Jumlah tumbuhan (produsen) dalam suatu ekosistem harus lebih banyak daripada jumlah hewan karena ...", options: ["tumbuhan tidak membutuhkan air", "tumbuhan berkembang biak lebih cepat", "tumbuhan menjadi sumber makanan bagi semua konsumen", "hewan tidak suka makan tumbuhan"], answer: 2, solution: "1. Semua hewan, baik herbivora maupun karnivora, bergantung pada tumbuhan. 2. Karnivora memakan herbivora yang memakan tumbuhan. 3. Jika produsen sedikit, makanan tidak cukup untuk seluruh konsumen sehingga produsen harus paling banyak." },
{ q: "Jika populasi katak di sawah menurun drastis karena ditangkap manusia, hal yang akan terjadi adalah ...", options: ["populasi belalang meningkat sehingga padi rusak", "populasi ular ikut meningkat", "padi tumbuh semakin subur", "belalang berubah menjadi karnivora"], answer: 0, solution: "1. Katak adalah pemangsa belalang dalam rantai makanan sawah. 2. Jika katak berkurang, belalang tidak ada yang memangsa sehingga jumlahnya meningkat. 3. Belalang yang banyak akan memakan daun padi hingga tanaman rusak." },
{ q: "Pohon jati dan pohon mahoni yang ditanam berdekatan akan berebut cahaya matahari dan zat hara. Hubungan kedua pohon tersebut termasuk ...", options: ["simbiosis parasitisme", "kompetisi", "predasi", "simbiosis mutualisme"], answer: 1, solution: "1. Jati dan mahoni sama-sama membutuhkan cahaya matahari dan zat hara. 2. Keduanya bersaing mendapatkan kebutuhan yang sama dan terbatas. 3. Persaingan antar makhluk hidup untuk kebutuhan yang sama disebut kompetisi." },
{ q: "Kutu rambut hidup di kepala manusia dan mengisap darah. Manusia merasa gatal dan dirugikan. Hubungan kutu dan manusia termasuk simbiosis ...", options: ["parasitisme", "netralisme", "mutualisme", "komensalisme"], answer: 0, solution: "1. Kutu diuntungkan karena mendapat makanan berupa darah manusia. 2. Manusia dirugikan karena kulit kepala gatal dan bisa luka. 3. Hubungan yang menguntungkan satu pihak dan merugikan pihak lain disebut parasitisme." },
{ q: "Ikan badut hidup di antara tentakel anemon laut. Ikan badut terlindung dari pemangsa, sedangkan anemon dibersihkan dari sisa makanan oleh ikan badut. Hubungan keduanya termasuk simbiosis ...", options: ["kompetisi", "mutualisme", "parasitisme", "komensalisme"], answer: 1, solution: "1. Ikan badut diuntungkan karena mendapat perlindungan dari tentakel anemon. 2. Anemon diuntungkan karena dibersihkan dari sisa makanan. 3. Karena keduanya saling diuntungkan, hubungan ini disebut simbiosis mutualisme." },
{ q: "Gulma (rumput liar) tumbuh di sela tanaman padi dan berebut air serta zat hara dengan padi. Hubungan gulma dan padi termasuk ...", options: ["simbiosis mutualisme", "simbiosis komensalisme", "kompetisi", "predasi"], answer: 2, solution: "1. Gulma dan padi sama-sama membutuhkan air dan zat hara dari tanah. 2. Keduanya bersaing mendapatkan kebutuhan yang sama. 3. Persaingan ini disebut kompetisi, dan petani mencabut gulma agar padi tumbuh subur." },
{ q: "Peran penting pengurai (jamur dan bakteri) dalam perputaran zat di alam adalah ...", options: ["mengubah sisa makhluk hidup menjadi zat hara yang diserap tumbuhan", "memakan hewan herbivora", "menghasilkan oksigen untuk bernapas", "membuat makanan melalui fotosintesis"], answer: 0, solution: "1. Sisa makhluk hidup seperti daun gugur dan bangkai mengandung zat yang masih berguna. 2. Pengurai menguraikan sisa tersebut menjadi zat hara yang sederhana. 3. Zat hara diserap akar tumbuhan untuk tumbuh, sehingga zat terus berputar di alam." },
{ q: "Petani memasang rumah burung hantu di sawah. Tujuan petani tersebut adalah ...", options: ["agar burung hantu bertelur di sawah", "menakuti burung pipit pemakan padi", "agar sawah terlihat indah", "mengendalikan hama tikus secara alami"], answer: 3, solution: "1. Burung hantu adalah pemangsa tikus dalam rantai makanan sawah. 2. Dengan adanya rumah burung hantu, populasi burung hantu meningkat. 3. Tikus yang menjadi hama padi akan dimangsa sehingga jumlahnya terkendali tanpa pestisida." },
{ q: "Kelompok hewan berikut yang semuanya termasuk karnivora adalah ...", options: ["kupu-kupu, lebah, dan semut", "sapi, kambing, dan kerbau", "harimau, singa, dan buaya", "ayam, bebek, dan tikus"], answer: 2, solution: "1. Karnivora adalah hewan pemakan daging atau hewan lain. 2. Harimau memangsa rusa, singa memangsa zebra, buaya memangsa ikan. 3. Sapi dan kambing adalah herbivora, sedangkan ayam dan tikus adalah omnivora." },
{ q: "Bunglon dan katak memakan serangga seperti jangkrik dan nyamuk. Hewan pemakan serangga seperti bunglon dan katak disebut ...", options: ["herbivora", "karnivora", "omnivora", "insektivora"], answer: 3, solution: "1. Serangga adalah hewan kecil seperti jangkrik dan nyamuk. 2. Bunglon menangkap serangga dengan lidahnya yang panjang dan lengket. 3. Hewan yang khusus memakan serangga disebut insektivora." },
{ q: "Urutan rantai makanan yang benar adalah ...", options: ["produsen → konsumen → pengurai", "pengurai → produsen → konsumen", "konsumen → pengurai → produsen", "konsumen → produsen → pengurai"], answer: 0, solution: "1. Rantai makanan selalu diawali produsen, yaitu tumbuhan hijau. 2. Produsen dimakan konsumen tingkat I, lalu dimakan konsumen tingkat berikutnya. 3. Sisa makhluk hidup yang mati diuraikan oleh pengurai sehingga zat kembali ke tanah." },
{ q: "Cacing tanah menggemburkan tanah dan kotorannya menyuburkan tanah. Peran cacing tanah dalam ekosistem adalah ...", options: ["pengurai", "konsumen puncak", "produsen", "konsumen tingkat I"], answer: 0, solution: "1. Cacing tanah memakan sisa daun dan bahan organik yang membusuk di tanah. 2. Cacing membantu menguraikan sisa makhluk hidup menjadi zat yang menyuburkan tanah. 3. Karena membantu penguraian, cacing tanah berperan sebagai pengurai." },
{ q: "Air laut yang terkena panas matahari berubah menjadi uap air dan naik ke udara. Tahap daur air ini disebut ...", options: ["infiltrasi", "kondensasi", "presipitasi", "evaporasi"], answer: 3, solution: "1. Panas matahari memanaskan air laut, sungai, dan danau. 2. Air yang panas berubah wujud menjadi uap air yang naik ke udara. 3. Perubahan air menjadi uap air karena panas disebut evaporasi atau penguapan." },
{ q: "Tumbuhan mengeluarkan uap air melalui daunnya ke udara. Proses pengeluaran uap air oleh tumbuhan ini disebut ...", options: ["fotosintesis", "transpirasi", "respirasi", "kondensasi"], answer: 1, solution: "1. Daun tumbuhan memiliki lubang kecil bernama stomata. 2. Melalui stomata, tumbuhan melepaskan uap air ke udara. 3. Pengeluaran uap air oleh tumbuhan disebut transpirasi atau penguapan tumbuhan." },
{ q: "Uap air yang naik ke udara berubah menjadi titik-titik air halus pembentuk awan. Perubahan wujud ini disebut ...", options: ["mengembun", "mencair", "menyublim", "menguap"], answer: 0, solution: "1. Semakin ke atas, suhu udara semakin dingin. 2. Uap air yang dingin berubah menjadi titik-titik air yang sangat kecil. 3. Perubahan uap air menjadi titik air disebut mengembun atau kondensasi, dan kumpulan titik air inilah yang menjadi awan." },
{ q: "Titik-titik air di awan yang semakin banyak dan berat akhirnya jatuh ke bumi sebagai hujan. Tahap daur air ini disebut ...", options: ["presipitasi", "transpirasi", "evaporasi", "kondensasi"], answer: 0, solution: "1. Titik air di awan terus bertambah karena pengembunan uap air. 2. Ketika sudah terlalu berat, titik air tidak mampu melayang lagi. 3. Jatuhnya air dari awan ke bumi sebagai hujan disebut presipitasi." },
{ q: "Sebagian air hujan meresap ke dalam tanah dan menjadi cadangan air di dalam bumi. Proses peresapan air ke dalam tanah ini disebut ...", options: ["presipitasi", "infiltrasi", "evaporasi", "kondensasi"], answer: 1, solution: "1. Tidak semua air hujan mengalir di permukaan menjadi sungai. 2. Sebagian air masuk ke pori-pori tanah dan tersimpan sebagai air tanah. 3. Proses meresapnya air ke dalam tanah disebut infiltrasi." },
{ q: "Sumber energi utama yang menggerakkan daur air di bumi adalah ...", options: ["angin", "matahari", "bulan", "gunung berapi"], answer: 1, solution: "1. Daur air diawali dengan penguapan air laut dan sungai. 2. Penguapan membutuhkan panas yang sangat besar. 3. Panas tersebut berasal dari matahari, sehingga matahari adalah penggerak utama daur air." },
{ q: "Embun yang menempel di daun pada pagi hari terbentuk karena ...", options: ["uap air mengembun saat suhu udara turun di malam hari", "hujan turun rintik-rintik semalam", "akar memompa air ke daun", "daun mengeluarkan air saat malam"], answer: 0, solution: "1. Pada malam hari suhu udara menjadi dingin. 2. Uap air di udara yang menyentuh permukaan daun yang dingin berubah menjadi titik air. 3. Titik air inilah yang kita lihat sebagai embun di pagi hari." },
{ q: "Awan yang tampak gelap dan tebal biasanya menandakan ...", options: ["angin bertiup kencang", "matahari bersinar terik", "cuaca akan cerah", "akan segera turun hujan"], answer: 3, solution: "1. Awan gelap mengandung sangat banyak titik air. 2. Karena banyaknya titik air, cahaya matahari sulit menembus sehingga awan tampak gelap. 3. Titik air yang terlalu berat akan segera jatuh sebagai hujan." },
{ q: "Mentega yang dipanaskan di wajan akan meleleh menjadi minyak. Perubahan wujud ini disebut ...", options: ["mengembun", "membeku", "mencair", "menguap"], answer: 2, solution: "1. Mentega semula berwujud padat. 2. Setelah dipanaskan, mentega berubah menjadi cair atau minyak. 3. Perubahan wujud dari padat menjadi cair karena panas disebut mencair." },
{ q: "Pakaian basah yang dijemur di bawah terik matahari lama-lama menjadi kering. Hal ini terjadi karena air pada pakaian ...", options: ["meresap ke dalam benang", "menguap menjadi uap air", "diserap oleh matahari", "berubah menjadi embun"], answer: 1, solution: "1. Panas matahari memanaskan air yang menempel pada pakaian. 2. Air berubah wujud menjadi uap air yang tidak terlihat dan naik ke udara. 3. Karena airnya hilang menguap, pakaian menjadi kering." },
{ q: "Dinding luar gelas berisi es menjadi basah oleh tetesan air. Tetesan air tersebut berasal dari ...", options: ["uap air di udara yang mengembun pada dinding gelas yang dingin", "es yang mencair di dalam gelas", "gelas yang bocor halus", "air es yang merembes keluar gelas"], answer: 0, solution: "1. Dinding gelas menjadi sangat dingin karena es di dalamnya. 2. Uap air di udara yang menyentuh dinding gelas yang dingin berubah menjadi titik air. 3. Jadi tetesan air berasal dari pengembunan uap air, bukan dari gelas yang bocor." },
{ q: "Kapur barus yang diletakkan di lemari lama-kelamaan mengecil dan habis tanpa meleleh. Perubahan wujud ini disebut ...", options: ["menyublim", "membeku", "mencair", "menguap"], answer: 0, solution: "1. Kapur barus semula berwujud padat. 2. Kapur barus langsung berubah menjadi gas tanpa melalui wujud cair terlebih dahulu. 3. Perubahan wujud dari padat langsung menjadi gas disebut menyublim." },
{ q: "Air yang terus dipanaskan hingga mendidih akan berubah menjadi ...", options: ["awan", "es", "embun", "uap air"], answer: 3, solution: "1. Air mendidih pada suhu yang sangat panas. 2. Air yang mendidih berubah wujud menjadi gas yang tidak terlihat. 3. Gas dari air panas ini disebut uap air." },
{ q: "Sungai mengalir dan bermuara ke laut, lalu air laut menguap dan turun lagi sebagai hujan. Hal ini menunjukkan bahwa daur air ...", options: ["akan berhenti jika musim kemarau", "berlangsung terus-menerus tanpa henti", "hanya terjadi di laut", "membutuhkan bantuan manusia"], answer: 1, solution: "1. Air yang turun sebagai hujan mengalir melalui sungai kembali ke laut. 2. Di laut, air menguap lagi dan membentuk awan serta hujan. 3. Perputaran ini terjadi berulang-ulang tanpa henti, sehingga disebut daur atau siklus air." },
{ q: "Air tanah yang tersimpan di dalam bumi dapat muncul ke permukaan sebagai ...", options: ["mata air", "embun", "kabut", "hujan"], answer: 0, solution: "1. Air hujan yang meresap tersimpan di lapisan tanah sebagai air tanah. 2. Di daerah tertentu, air tanah keluar sendiri ke permukaan. 3. Aliran air tanah yang muncul ke permukaan disebut mata air." },
{ q: "Kabut tipis yang sering terlihat di daerah pegunungan pada pagi hari sebenarnya adalah ...", options: ["debu yang beterbangan", "awan yang jatuh ke bumi", "asap kendaraan bermotor", "kumpulan titik-titik air hasil pengembunan uap air"], answer: 3, solution: "1. Udara pegunungan pada pagi hari sangat dingin. 2. Uap air di udara mengembun menjadi titik-titik air yang sangat kecil dan melayang. 3. Kumpulan titik air yang melayang di dekat permukaan tanah inilah yang disebut kabut." },
{ q: "Es batu yang dibiarkan di atas meja lama-lama mencair menjadi air. Es mencair karena ...", options: ["es mengeluarkan dingin", "menerima panas dari udara sekitar", "tekanan udara yang besar", "meja menyerap air"], answer: 1, solution: "1. Es batu bersuhu dingin, sedangkan udara sekitar lebih hangat. 2. Panas dari udara berpindah ke es batu. 3. Karena menerima panas, es berubah wujud dari padat menjadi cair atau mencair." },
{ q: "Urutan tahapan daur air yang benar adalah ...", options: ["hujan → menguap → awan → meresap", "menguap → membentuk awan → hujan → meresap ke tanah", "awan → menguap → hujan → mengembun", "meresap → hujan → menguap → awan"], answer: 1, solution: "1. Daur air diawali air yang menguap karena panas matahari. 2. Uap air naik lalu mengembun membentuk awan. 3. Titik air di awan jatuh sebagai hujan, lalu sebagian meresap ke tanah dan kembali ke laut." },
{ q: "Air laut terasa asin, tetapi air hujan terasa tawar. Hal ini karena ...", options: ["hanya air yang menguap, sedangkan garam tertinggal di laut", "awan menyaring garam", "hujan bercampur air sungai", "garam menguap bersama air"], answer: 0, solution: "1. Air laut mengandung garam yang terlarut. 2. Saat terjadi penguapan, hanya air yang berubah menjadi uap dan naik ke udara. 3. Garam tidak ikut menguap sehingga tertinggal di laut, dan hujan yang turun pun tawar." },
{ q: "Awan terbentuk di langit yang tinggi karena ...", options: ["burung membawa air ke atas", "matahari mendorong air ke atas", "udara di ketinggian semakin dingin sehingga uap air mengembun", "angin meniup air laut ke langit"], answer: 2, solution: "1. Uap air dari penguapan naik ke lapisan udara yang tinggi. 2. Semakin tinggi, suhu udara semakin dingin. 3. Uap air yang kedinginan mengembun menjadi titik-titik air yang berkumpul membentuk awan." },
{ q: "Bunglon dapat mengubah warna kulitnya menyerupai warna lingkungan sekitarnya. Kemampuan ini berguna untuk ...", options: ["menunjukkan rasa takut", "menarik perhatian mangsa", "menyamarkan diri dari musuh dan mangsa", "menghangatkan tubuh"], answer: 2, solution: "1. Warna kulit bunglon berubah mengikuti warna daun atau ranting di sekitarnya. 2. Dengan warna yang sama seperti lingkungan, bunglon sulit terlihat. 3. Kemampuan menyamarkan diri ini disebut kamuflase, berguna untuk bersembunyi dari musuh dan mengintai mangsa." },
{ q: "Ketika ekornya dipegang musuh, cicak akan memutuskan ekornya lalu lari. Cara cicak melindungi diri ini disebut ...", options: ["mimikri", "autotomi", "kamuflase", "hibernasi"], answer: 1, solution: "1. Ekor cicak yang putus tetap bergerak-gerak sehingga perhatian musuh teralihkan. 2. Cicak memanfaatkan kesempatan itu untuk kabur menyelamatkan diri. 3. Kemampuan memutuskan bagian tubuh untuk melindungi diri disebut autotomi, dan ekor cicak akan tumbuh kembali." },
{ q: "Siput memiliki tubuh yang lunak. Untuk melindungi diri dari musuh, siput ...", options: ["bersembunyi ke dalam cangkang yang keras", "memutuskan ekornya", "mengubah warna kulit", "menyemprotkan tinta hitam"], answer: 0, solution: "1. Tubuh siput lunak dan mudah diserang musuh. 2. Siput memiliki cangkang keras yang menutupi tubuhnya. 3. Saat bahaya, siput menarik tubuhnya masuk ke dalam cangkang sehingga musuh sulit memangsanya." },
{ q: "Saat dikejar musuh, cumi-cumi menyemprotkan cairan hitam ke air. Cairan tinta tersebut berfungsi untuk ...", options: ["menarik perhatian teman", "menghangatkan air", "meracuni musuh", "mengaburkan pandangan musuh agar cumi-cumi bisa kabur"], answer: 3, solution: "1. Tinta hitam yang disemprotkan membuat air di sekitarnya menjadi gelap. 2. Musuh tidak bisa melihat cumi-cumi dalam air yang gelap. 3. Cumi-cumi memanfaatkan keadaan itu untuk kabur dengan cepat." },
{ q: "Unta dapat bertahan hidup berhari-hari di gurun tanpa makan dan minum karena ...", options: ["kakinya yang panjang menyimpan air", "unta tidak pernah merasa lapar", "punuknya menyimpan cadangan lemak sebagai sumber energi", "unta memakan pasir gurun"], answer: 2, solution: "1. Di gurun sulit ditemukan makanan dan air. 2. Unta menyimpan lemak sebagai cadangan makanan di punuknya. 3. Saat tidak ada makanan, tubuh unta menggunakan lemak di punuk sebagai sumber energi." },
{ q: "Beruang kutub dapat bertahan hidup di daerah bersalju yang sangat dingin karena memiliki ...", options: ["bulu tebal dan lapisan lemak di bawah kulit", "kebiasaan berjemur setiap hari", "tubuh yang kecil mungil", "kulit berwarna gelap"], answer: 0, solution: "1. Daerah kutub bersuhu sangat dingin dan berangin. 2. Bulu tebal beruang kutub menahan panas tubuh agar tidak keluar. 3. Lapisan lemak di bawah kulit juga menjaga tubuh tetap hangat." },
{ q: "Kelelawar dapat terbang dan menangkap mangsa dalam gua yang gelap gulita karena ...", options: ["menggunakan bunyi pantul untuk mengetahui arah", "mengikuti cahaya kunang-kunang", "mencium bau mangsa", "matanya sangat tajam"], answer: 0, solution: "1. Di dalam gua yang gelap, mata kelelawar tidak banyak membantu. 2. Kelelawar mengeluarkan bunyi dan mendengarkan pantulannya. 3. Dari bunyi pantul itu kelelawar tahu letak benda dan mangsa, cara ini disebut ekolokasi." },
{ q: "Ikan dapat mengambil oksigen untuk bernapas di dalam air dengan menggunakan ...", options: ["kulit", "sirip", "insang", "paru-paru"], answer: 2, solution: "1. Ikan hidup di air dan tidak bisa bernapas dengan paru-paru seperti manusia. 2. Ikan memiliki insang di sisi kepalanya. 3. Insang menyerap oksigen yang terlarut dalam air saat air melewatinya." },
{ q: "Bentuk tubuh ikan yang ramping dan pipih ke samping berguna untuk ...", options: ["menarik perhatian pasangan", "menakuti musuh", "memudahkan bergerak dan berenang di air", "menyimpan cadangan makanan"], answer: 2, solution: "1. Air memberi hambatan pada benda yang bergerak di dalamnya. 2. Tubuh yang ramping membelah air dengan mudah sehingga hambatannya kecil. 3. Bentuk tubuh seperti ini disebut streamline dan membuat ikan berenang cepat." },
{ q: "Katak memiliki kaki belakang yang panjang dan kuat. Kaki seperti ini berguna untuk ...", options: ["berenang cepat", "melompat jauh menghindari musuh", "menggali tanah", "memanjat pohon"], answer: 1, solution: "1. Katak hidup di dekat air dan sering diincar pemangsa. 2. Kaki belakang yang panjang dan berotot memberi tolakan kuat. 3. Dengan kaki itu katak dapat melompat jauh untuk kabur dari musuh atau menangkap serangga." },
{ q: "Lebah melindungi diri dari gangguan dengan cara ...", options: ["menyengat dengan sengat beracun", "memutuskan ekornya", "berpura-pura mati", "menyemprotkan tinta"], answer: 0, solution: "1. Lebah memiliki sengat di bagian belakang tubuhnya. 2. Sengat tersebut mengandung racun yang menimbulkan rasa sakit. 3. Musuh yang disengat akan kapok dan tidak mengganggu lebah lagi." },
{ q: "Landak dapat melindungi diri dari musuh karena tubuhnya ditutupi ...", options: ["sisik yang keras", "lendir yang licin", "bulu yang lembut", "duri yang tajam"], answer: 3, solution: "1. Tubuh landak dipenuhi duri tajam yang kaku. 2. Saat terancam, landak mengembangkan durinya. 3. Musuh yang mencoba memangsa akan tertusuk duri sehingga mengurungkan niatnya." },
{ q: "Burung kolibri memiliki paruh yang panjang, runcing, dan melengkung. Bentuk paruh ini berguna untuk ...", options: ["merobek daging mangsa", "mematuk biji-bijian yang keras", "mengisap nektar dari dalam bunga", "menyaring air di lumpur"], answer: 2, solution: "1. Kolibri memakan nektar atau madu bunga yang letaknya di dasar bunga. 2. Paruh yang panjang dan runcing dapat masuk ke dalam bunga yang sempit. 3. Bentuk paruh yang sesuai dengan makanannya ini disebut adaptasi." },
{ q: "Kantong semar memiliki kantong yang berisi cairan. Cairan di dalam kantong tersebut berfungsi untuk ...", options: ["menampung air hujan", "menangkap dan mencerna serangga sebagai makanan tambahan", "menarik kupu-kupu", "menyimpan cadangan air"], answer: 1, solution: "1. Kantong semar tumbuh di tanah yang miskin zat hara. 2. Kantongnya yang licin membuat serangga terpeleset masuk dan tenggelam dalam cairan. 3. Cairan itu mencerna serangga sehingga tumbuhan mendapat zat makanan tambahan." },
{ q: "Daun teratai lebar dan mengapung di permukaan air, sedangkan batangnya berongga. Ciri ini berguna agar teratai ...", options: ["dimakan ikan", "terbawa arus sungai", "tenggelam ke dasar kolam", "tidak tenggelam dan mendapat cahaya matahari"], answer: 3, solution: "1. Teratai hidup di air sehingga harus bisa mengapung. 2. Batang berongga berisi udara membuat teratai mengapung seperti pelampung. 3. Daun lebar yang mengapung menangkap cahaya matahari untuk fotosintesis." },
{ q: "Pangkal daun eceng gondok menggembung seperti balon. Bagian yang menggembung tersebut berfungsi untuk ...", options: ["menarik serangga", "menyerap air hujan", "menyimpan makanan", "membantu tumbuhan mengapung di air"], answer: 3, solution: "1. Eceng gondok hidup mengapung di permukaan air. 2. Bagian daun yang menggembung berisi udara. 3. Udara di dalamnya berfungsi seperti pelampung sehingga eceng gondok tidak tenggelam." },
{ q: "Pohon jati menggugurkan daunnya pada musim kemarau. Kebiasaan ini bertujuan untuk ...", options: ["menarik burung bersarang", "agar pohon terlihat indah", "mengurangi penguapan air dari daun", "memberi makan hewan"], answer: 2, solution: "1. Pada musim kemarau, air di tanah sangat sedikit. 2. Daun adalah tempat utama penguapan air pada tumbuhan. 3. Dengan menggugurkan daun, pohon jati mengurangi kehilangan air sehingga tetap hidup saat kemarau." },
{ q: "Batang bunga mawar dipenuhi duri-duri tajam. Duri tersebut berfungsi untuk ...", options: ["membantu fotosintesis", "melindungi diri dari hewan pemakan tumbuhan", "menyerap air hujan", "menarik lebah"], answer: 1, solution: "1. Hewan herbivora suka memakan daun dan batang tumbuhan. 2. Duri tajam pada batang mawar membuat hewan kesakitan jika menggigitnya. 3. Dengan begitu, duri melindungi mawar agar tidak dimakan hewan." },
{ q: "Laba-laba menangkap mangsanya dengan cara ...", options: ["menjerat dengan jaring yang lengket", "menyemprotkan racun dari jauh", "bersembunyi di dalam tanah", "mengejar dengan cepat"], answer: 0, solution: "1. Laba-laba membuat jaring dari benang halus yang lengket. 2. Serangga yang terbang menabrak jaring akan menempel dan tidak bisa lepas. 3. Laba-laba lalu mendekat dan memakan serangga yang terjerat." },
{ q: "Belalang memiliki kaki belakang yang besar dan kuat. Kaki tersebut berguna untuk ...", options: ["berenang di air", "memanjat batang pohon", "menggali tanah", "melompat jauh menghindari musuh"], answer: 3, solution: "1. Kaki belakang belalang berotot besar dan panjang. 2. Otot kaki memberi tolakan yang sangat kuat ke tanah. 3. Belalang dapat melompat jauh hingga puluhan kali panjang tubuhnya untuk kabur dari pemangsa." },
{ q: "Paus adalah mamalia yang hidup di laut. Saat muncul ke permukaan, paus bernapas melalui ...", options: ["kulit tubuhnya", "insang", "lubang sembur di atas kepalanya", "mulut yang lebar"], answer: 2, solution: "1. Paus bernapas dengan paru-paru, bukan insang, sehingga harus mengambil udara. 2. Paus memiliki lubang khusus di atas kepala yang disebut lubang sembur. 3. Saat muncul ke permukaan, paus mengembuskan udara lama dan menghirup udara baru melalui lubang itu." },
{ q: "Kura-kura berjalan lambat sehingga mudah ditangkap musuh. Untuk melindungi diri, kura-kura ...", options: ["berlari dengan cepat", "menyembunyikan tubuh ke dalam tempurung yang keras", "menyemprotkan tinta", "mengubah warna tubuh"], answer: 1, solution: "1. Kura-kura memiliki tempurung keras yang menutupi punggung dan perutnya. 2. Saat bahaya, kura-kura menarik kepala dan kakinya masuk ke dalam tempurung. 3. Tempurung yang keras sulit ditembus musuh sehingga kura-kura aman." },
{ q: "Kupu-kupu mengisap madu bunga dengan alat yang bisa menggulung dan menjulur seperti belalai. Alat ini disebut ...", options: ["antena", "sengat", "rahang", "probosis"], answer: 3, solution: "1. Madu bunga terletak di bagian dalam bunga yang sempit. 2. Kupu-kupu memiliki alat pengisap panjang seperti sedotan. 3. Alat pengisap ini disebut probosis, bisa digulung saat tidak dipakai dan dijulurkan saat mengisap madu." },
{ q: "Daun lidah buaya tebal dan mengandung banyak lendir. Ciri daun seperti ini berguna untuk ...", options: ["menarik kupu-kupu", "melindungi dari banjir", "menangkap serangga", "menyimpan cadangan air agar tahan di tempat kering"], answer: 3, solution: "1. Lidah buaya tumbuh di daerah kering yang jarang hujan. 2. Daunnya yang tebal menyimpan air dan lendir sebagai cadangan. 3. Saat kemarau, cadangan air ini digunakan sehingga lidah buaya tetap segar." },
{ q: "Trenggiling memiliki tubuh yang dilindungi sisik-sisik keras. Saat terancam bahaya, trenggiling akan ...", options: ["menyemprotkan bau busuk", "berlari sangat cepat", "menggulungkan tubuhnya seperti bola", "terbang menjauh"], answer: 2, solution: "1. Sisik keras trenggiling menutupi seluruh tubuhnya seperti baju zirah. 2. Saat bahaya, trenggiling menggulung tubuhnya hingga menyerupai bola. 3. Dalam posisi menggulung, bagian tubuh yang lunak terlindungi dan musuh sulit memangsanya." },
{ q: "Dua kutub magnet yang senama (utara dengan utara) jika didekatkan akan ...", options: ["tarik-menarik", "tolak-menolak", "menempel kuat", "tidak terjadi apa-apa"], answer: 1, solution: "1. Setiap magnet memiliki dua kutub, yaitu kutub utara dan kutub selatan. 2. Kutub yang sama jenisnya saling menolak. 3. Jadi kutub utara didekatkan kutub utara akan tolak-menolak, sedangkan kutub berbeda akan tarik-menarik." },
{ q: "Jarum kompas selalu menunjuk arah utara dan selatan. Hal ini terjadi karena jarum kompas ...", options: ["merupakan magnet kecil yang tertarik oleh magnet bumi", "ditarik oleh bintang utara", "mengikuti arah matahari", "digerakkan oleh angin"], answer: 0, solution: "1. Jarum kompas terbuat dari magnet kecil yang dapat berputar bebas. 2. Bumi sendiri bersifat seperti magnet raksasa. 3. Jarum kompas tertarik oleh medan magnet bumi sehingga selalu menunjuk arah utara-selatan." },
{ q: "Paku besi dapat dijadikan magnet sementara dengan cara ...", options: ["dipanaskan di atas api", "direndam dalam air garam", "digosokkan dengan magnet ke satu arah berulang kali", "dipukul-pukul dengan palu"], answer: 2, solution: "1. Benda dari besi dapat dijadikan magnet dengan cara digosok. 2. Gosokkan sebuah magnet pada paku besi ke satu arah saja secara berulang-ulang. 3. Paku akan menjadi magnet sementara yang dapat menarik benda logam kecil." },
{ q: "Bel listrik di rumah dapat berbunyi karena di dalamnya terdapat magnet sementara yang dibuat dengan cara ...", options: ["menjatuhkan magnet", "menggosokkan besi ke kain", "mengalirkan listrik pada lilitan kawat", "memanaskan besi"], answer: 2, solution: "1. Magnet sementara hanya bersifat magnet saat ada aliran listrik. 2. Caranya dengan melilitkan kawat pada besi lalu mengalirkan listrik, disebut elektromagnet. 3. Saat tombol bel ditekan, listrik mengalir dan elektromagnet menarik pemukul hingga bel berbunyi." },
{ q: "Penggaris plastik yang digosok-gosokkan pada rambut kering dapat menarik potongan kertas kecil. Peristiwa ini menunjukkan adanya ...", options: ["magnet", "listrik statis", "gaya gravitasi", "gaya gesek"], answer: 1, solution: "1. Menggosok penggaris pada rambut memindahkan muatan listrik ke penggaris. 2. Penggaris menjadi bermuatan listrik dan dapat menarik benda ringan. 3. Listrik yang diam tidak mengalir ini disebut listrik statis." },
{ q: "Lampu senter dapat menyala karena memiliki rangkaian listrik yang tertutup, yaitu ...", options: ["baterai dan lampu yang terpisah", "kabel yang terputus", "lampu tanpa baterai", "baterai, kabel, dan lampu yang tersambung"], answer: 3, solution: "1. Agar lampu menyala, arus listrik harus mengalir membentuk lingkaran tertutup. 2. Baterai sebagai sumber listrik dihubungkan kabel ke lampu. 3. Jika rangkaian terputus, misalnya kabel lepas, lampu akan padam." },
{ q: "Gagang obeng dan tang dilapisi plastik atau karet. Lapisan tersebut berfungsi sebagai isolator yang artinya ...", options: ["membuat alat lebih berat", "menambah keindahan alat", "menghantarkan listrik dengan baik", "tidak menghantarkan listrik sehingga aman dipegang"], answer: 3, solution: "1. Saat memperbaiki listrik, tangan bisa terkena aliran listrik dari alat. 2. Plastik dan karet tidak dapat menghantarkan listrik atau disebut isolator. 3. Lapisan isolator melindungi tangan agar tidak tersengat listrik." },
{ q: "Batu kerikil dimasukkan ke dalam gelas berisi air, bentuknya tetap seperti semula. Hal ini menunjukkan bahwa benda padat ...", options: ["dapat mengalir", "bentuknya selalu berubah", "bentuknya tetap walaupun dipindah wadah", "mengikuti bentuk wadahnya"], answer: 2, solution: "1. Benda padat memiliki bentuk yang tetap. 2. Batu kerikil dipindah ke gelas, mangkuk, atau tangan bentuknya tidak berubah. 3. Berbeda dengan air yang selalu mengikuti bentuk wadahnya karena benda cair." },
{ q: "Balon yang ditiup mengembang ke segala arah. Hal ini menunjukkan sifat gas atau udara, yaitu ...", options: ["bentuknya tetap", "mengisi seluruh ruang yang ditempatinya", "tidak dapat ditekan", "selalu bergerak ke atas"], answer: 1, solution: "1. Udara yang ditiupkan masuk ke dalam balon. 2. Udara menyebar dan menekan ke segala arah sehingga balon mengembang. 3. Sifat gas adalah mengisi seluruh ruang wadah yang ditempatinya." },
{ q: "Potongan kayu mengapung di air, sedangkan batu tenggelam. Hal ini terjadi karena ...", options: ["massa jenis kayu lebih kecil daripada air", "air menolak kayu", "batu menyerap air", "kayu lebih berat dari batu"], answer: 0, solution: "1. Benda mengapung atau tenggelam ditentukan oleh massa jenisnya dibanding air. 2. Massa jenis kayu lebih kecil daripada air sehingga kayu terdorong ke atas dan mengapung. 3. Massa jenis batu lebih besar daripada air sehingga batu tenggelam." },
{ q: "Sendok gula dimasukkan ke dalam teh hangat lalu diaduk hingga tidak terlihat lagi. Hal ini menunjukkan bahwa gula ...", options: ["mengendap di dasar gelas", "berubah menjadi teh", "menguap menjadi gas", "larut dalam air"], answer: 3, solution: "1. Gula yang diaduk dalam teh hangat lama-lama tidak terlihat. 2. Gula tidak hilang, tetapi menyebar merata di antara partikel air. 3. Peristiwa ini disebut melarut, berbeda dengan pasir yang tidak larut dan mengendap." },
{ q: "Mainan mobil-mobilan dapat bergerak karena di dalamnya terdapat baterai. Baterai pada mainan berfungsi sebagai ...", options: ["pemberat mainan", "hiasan mainan", "sumber energi listrik", "pengeras suara"], answer: 2, solution: "1. Mainan mobil membutuhkan energi untuk menggerakkan rodanya. 2. Baterai menyimpan energi kimia yang diubah menjadi energi listrik. 3. Energi listrik inilah yang menggerakkan motor mainan sehingga mobil berjalan." },
{ q: "Kabel listrik terbuat dari tembaga yang dibungkus plastik. Tembaga dipilih karena ...", options: ["tembaga penghantar listrik yang baik", "tembaga tidak menghantarkan listrik", "tembaga berwarna indah", "tembaga sangat murah"], answer: 0, solution: "1. Kabel harus mengalirkan listrik dari sumber ke lampu atau alat lain. 2. Tembaga termasuk konduktor, yaitu benda yang menghantarkan listrik dengan baik. 3. Bagian luar dibungkus plastik yang isolator agar aman saat disentuh." },
{ q: "Es batu mencair menjadi air, dan air dapat dibekukan kembali menjadi es. Hal ini menunjukkan bahwa perubahan wujud benda ...", options: ["dapat kembali ke wujud semula", "selalu membutuhkan api", "tidak bisa diamati", "hanya bisa terjadi satu kali"], answer: 0, solution: "1. Es mencair karena menerima panas menjadi air. 2. Air yang didinginkan di freezer membeku kembali menjadi es. 3. Jadi perubahan wujud benda dapat bolak-balik atau kembali ke wujud semula." },
{ q: "Sirup dituang dari botol ke dalam gelas, bentuknya berubah mengikuti bentuk gelas. Hal ini menunjukkan bahwa benda cair ...", options: ["mengisi seluruh ruang seperti gas", "dapat dilihat menembus wadah", "bentuknya tetap seperti benda padat", "bentuknya berubah mengikuti wadah, tetapi volumenya tetap"], answer: 3, solution: "1. Sirup di dalam botol berbentuk seperti botol. 2. Setelah dituang ke gelas, sirup berbentuk seperti gelas. 3. Jadi benda cair bentuknya mengikuti wadah, tetapi jumlah atau volumenya tetap sama." }
  ]
};
